/* Strategic Mastery Academy — moduli didattici dei pilastri Detective Intelligence (det) e Multi-Layer Planning (pln), livelli L0–L5.
   Nota didattica: gli esercizi dell'app sono simulazioni a scelta chiusa; provano che sai applicare un metodo a casi dati, non che lo applichi nella vita reale.
   Convenzione locale di mc: la risposta giusta si scrive per PRIMA e viene collocata in una posizione a rotazione deterministica. */
(function (ST) {
  'use strict';
  const M = ST.sma, { fill, order } = ST.content, C = ST.content;
  const T = o => M.topic(o);
  let rot = 0;
  const mc = (q, o, why) => { const n = o.length, k = Math.floor(((Math.imul(++rot, 2654435761) >>> 0) / 4294967296) * n), rest = o.slice(1); rest.splice(k, 0, o[0]); return C.mc(q, rest, k, why); };

  /* ================= DET · L0 ================= */
  T({ id: 'sma-det-l0-fatti-ipotesi-opinioni', pillar: 'det', stage: 'L0', title: 'Fatti, ipotesi e opinioni',
    summary: 'Separare ciò che si osserva da ciò che si ipotizza e da ciò che si giudica: la base di ogni ragionamento da investigatore.',
    objectives: ['Classificare un enunciato come fatto, ipotesi o opinione', 'Dire come si potrebbe controllare un fatto e come si potrebbe smentire un’ipotesi', 'Riconoscere tre errori semplici: salto alla conclusione, correlazione scambiata per causa, generalizzazione da un solo caso'],
    minutes: 18,
    pages: [
      { h: 'Tre tipi di frase', b: `Quando qualcuno ti racconta qualcosa, nella stessa frase si mescolano di solito **tre ingredienti diversi**:\n\n- **Fatto**: qualcosa che si può verificare con un’osservazione, una misura o un documento. Può anche essere falso, ma ha senso chiedersi «è vero o no?» e c’è un modo per controllare.\n- **Ipotesi**: una spiegazione provvisoria di ciò che si è visto. Va messa alla prova, e deve poter risultare sbagliata.\n- **Opinione (o valutazione)**: un giudizio di valore o di gusto («è fastidioso», «è un buon piano»). Non si verifica come un fatto: si discute con criteri e motivi.\n\n> «Il treno delle 7:40 è arrivato alle 8:05.» È un fatto: lo dice l’orario registrato.\n> «Ci sarà stato uno sciopero.» È un’ipotesi: spiegherebbe il ritardo, ma va controllata.\n> «Le ferrovie sono un disastro.» È un’opinione: dipende da cosa conti come «disastro».\n\nIl primo passo di ogni indagine è **etichettare**, anche solo mentalmente. Non per sminuire opinioni e ipotesi (servono!), ma per non trattarle come se fossero fatti.` },
      { h: 'Osservare prima di interpretare', b: `Il trucco più utile è **scrivere la scena in modo che una telecamera potrebbe registrarla**. Un’osservazione descrive ciò che si vede o si misura; un’interpretazione aggiunge un perché o uno stato d’animo.\n\n> Interpretazione: «Il collega era scocciato con me.» Osservazione: «Non ha risposto al mio saluto e ha chiuso la porta della stanza.»\n> Interpretazione: «Il sito è lento perché il server è vecchio.» Osservazione: «La pagina impiega 9 secondi a caricarsi da rete mobile e 2 secondi dal Wi-Fi di casa.»\n\nLa versione «da telecamera» è più povera, ma lascia aperte **più spiegazioni**: il collega poteva non aver sentito, essere al telefono, avere fretta. L’interpretazione chiude troppo presto la porta alle alternative.\n\nRegola pratica: se nella frase compaiono **parole come «perché», «evidentemente», «di sicuro», «apposta»**, c’è quasi sempre una supposizione travestita da fatto.` },
      { h: 'Come si controlla un fatto', b: `Un fatto è tale perché **esiste un modo per controllarlo**. Prima di accettarlo chiediti tre cose:\n\n1. **Chi o che cosa l’ha rilevato?** Una misura diretta (un contatore, una ricevuta, un orario ufficiale) pesa più di un «mi pare».\n2. **L’ha visto di persona o l’ha sentito dire?** Una testimonianza diretta è più solida di una catena di «mi hanno detto che».\n3. **Posso verificarlo io in pochi minuti?** Spesso sì: rileggere il messaggio originale, guardare l’estratto conto, riprovare a caricare la pagina.\n\n> «Ho speso 340 euro questo mese in cibo da asporto.» Verifica: sommi le voci dell’estratto conto. Se il totale è 215, il «fatto» era un ricordo gonfiato.\n> «La batteria dura meno di prima.» Verifica: guardi la percentuale a inizio e fine giornata per tre giorni. Un confronto con numeri vale più della sensazione.\n\nNota: **verificabile non significa verificato**. Finché non hai controllato, conta come «dichiarato», non come «accertato».` },
      { h: 'L’ipotesi: una scommessa che può perdere', b: `Un’ipotesi utile ha due caratteristiche: **spiega** i fatti e **può essere smentita**. «Qualcosa è successo per qualche motivo» non rischia nulla e quindi non insegna nulla.\n\nPer rendere un’ipotesi verificabile, chiediti: **«Se fosse vera, che cosa dovrei vedere? E che cosa NON dovrei vedere?»**\n\n> Ipotesi: «Dormo male perché bevo il caffè dopo le 16.» Se è vera, nelle sere senza caffè pomeridiano dovrei addormentarmi più in fretta. Se in una settimana senza caffè dormo uguale, l’ipotesi esce indebolita.\n> Ipotesi: «L’app si blocca perché la memoria è piena.» Se è vera, liberando 2 GB il problema dovrebbe sparire o ridursi.\n\nTieni sempre **più di una ipotesi** in campo: la prima che ti viene in mente è comoda, non necessariamente giusta. Già due o tre alternative cambiano il modo di cercare: invece di raccogliere prove a favore di una sola, cerchi la prova che **distingue** tra loro.` },
      { h: 'Deduzione e induzione, in piccolo', b: `Due modi di ragionare che userai spesso, con garanzie molto diverse.\n\n**Deduzione**: dalle premesse alla conclusione necessaria. Se le premesse sono vere e il ragionamento è corretto, la conclusione **non può** essere falsa.\n> Premesse: «Il negozio chiude alle 19. Sono le 19:30.» Conclusione: «Il negozio è chiuso.» (Salvo che una premessa sia sbagliata: la deduzione è solida quanto le sue premesse.)\n\n**Induzione**: da casi osservati a una regola probabile. La conclusione è **plausibile, mai certa**.\n> Per tre mattine di fila l’autobus delle 8:10 passa alle 8:20. Conclusione: «Di solito ritarda di circa 10 minuti.» Se domani passa in orario, la regola non è «falsa»: era una tendenza, non una legge.\n\nL’errore tipico è usare l’induzione con il tono della deduzione: «Succede sempre così» dopo due casi. Una buona abitudine è aggiungere **«finora»** e **«di solito»** quando generalizzi, e contare su quanti casi lo stai facendo.` },
      { h: 'Caso svolto: «il Wi-Fi non funziona»', b: `Sono le 21:00 e il portatile non carica le pagine. Un racconto confuso sarebbe: «La rete di casa è saltata, è colpa del provider, lo sapevo!». Separiamo.\n\n**Passo 1, fatti (da telecamera).** La pagina del sito di notizie non si carica. Il telefono, collegato allo stesso Wi-Fi, carica normalmente un’app di messaggi. Il portatile mostra il simbolo Wi-Fi connesso.\n\n**Passo 2, ipotesi concorrenti.** H1: problema solo del portatile (impostazioni, browser). H2: problema del sito di notizie. H3: problema della rete di casa. H4: problema del provider.\n\n**Passo 3, che cosa distingue?** Se H3 o H4 fossero vere, anche il telefono avrebbe problemi: ma il telefono funziona. Quindi H3 e H4 sono già **molto indebolite** (non escluse: l’app di messaggi potrebbe usare una connessione diversa).\n\n**Passo 4, test economici.** Aprire un altro sito sul portatile: se carica, H2 diventa probabile. Se non carica nulla, H1 sale.\n\n**Passo 5, opinioni in quarantena.** «Il provider fa schifo» è un giudizio, magari motivato da esperienze passate: non entra nel conto finché non ci sono fatti.\n\n> Risultato del test: un altro sito carica subito. Conclusione provvisoria: era il sito di notizie. Se tra un’ora ancora non carica, lo si segnala come **fatto ripetuto**, non come sospetto.` },
      { h: 'Tre inciampi frequenti, e che cosa provi qui', b: `**1. Salto alla conclusione.** Dalla prima spiegazione plausibile si passa subito alla decisione. Rimedio: scrivere almeno una seconda ipotesi.\n\n**2. Correlazione scambiata per causa.** Due cose accadono insieme e si dice che una causa l’altra.\n> «Nelle settimane in cui faccio più ore di studio il voto è più alto, quindi più ore causano voti più alti.» Può darsi, ma le settimane di studio intenso potrebbero coincidere con argomenti che già conosci bene. Prima di concludere, cerca almeno una terza spiegazione.\n\n**3. Generalizzazione da un solo caso.** «Ho comprato da quel negozio una volta e il pacco è arrivato in ritardo: sono tutti inaffidabili.»\n\n**Che cosa prova questo modulo e che cosa no.** Gli esercizi ti mostrano se, **dato un testo**, riesci a separare fatti, ipotesi e opinioni. Non misurano se lo fai quando sei arrabbiato, di fretta o coinvolto: per quello serve applicazione reale, per esempio rileggendo una discussione vera e sottolineando le supposizioni. Nei prossimi livelli faremo proprio questo passo dopo passo.` }
    ],
    exercises: [
      mc('«Dal contratto risulta che la consegna è prevista per giovedì 12.» Che tipo di enunciato è, se riporta ciò che dice il documento?', ['Un fatto dichiarato, da controllare sul documento originale', 'Un’ipotesi, perché riguarda un evento che deve ancora accadere', 'Un’opinione, perché non l’hai verificato di persona', 'Una deduzione, perché indica una data precisa e certa'], 'Ciò che il documento dice è un dato controllabile (dichiarato); se la consegna avverrà davvero è un’altra questione.'),
      mc('Quale riformulazione è un’osservazione «da telecamera»?', ['Il cameriere ha portato il conto senza che lo chiedessi', 'Il cameriere voleva farci andare via il più in fretta possibile', 'Il cameriere è stato scortese con noi per tutta la serata', 'Il cameriere era di cattivo umore e si vedeva benissimo'], 'Le altre tre attribuiscono intenzioni o stati d’animo: sono interpretazioni.'),
      mc('Un amico dice: «Da quando uso questa app dormo meglio, quindi l’app funziona». Che cosa manca per sostenere la causa?', ['Una terza spiegazione da escludere, per esempio il periodo con meno stress', 'Nessuna aggiunta: il miglioramento osservato basta come prova del nesso', 'Un parere di altri utenti che hanno scaricato l’app una sola volta', 'Un voto di soddisfazione dato dall’amico stesso al termine del mese'], 'La coincidenza nel tempo non basta: vanno considerate altre cause possibili e, se si può, un confronto con periodi senza app.'),
      mc('Quale ipotesi è meglio formulata, cioè può essere smentita da un’osservazione?', ['Il router si surriscalda: dopo un riavvio dovrebbe restare stabile più a lungo', 'La connessione ha qualche problema che prima o poi si manifesterà del tutto', 'Il Wi-Fi funziona male perché oggi è una giornata sfortunata per la rete', 'La rete è fatta così e nessuna prova potrà mai chiarire il motivo'], 'Predice qualcosa di osservabile (dopo il riavvio, più stabilità) e quindi può risultare sbagliata.'),
      mc('Quale delle seguenti NON è un esempio di induzione?', ['Tutti i mammiferi allattano; il delfino è un mammifero; quindi il delfino allatta', 'Le ultime quattro consegne di quel corriere sono arrivate in ritardo; il prossimo ritarderà probabilmente', 'Ogni volta che ho studiato di sera ho ricordato meno; forse conviene studiare al mattino', 'Dopo tre test con il cavo nuovo il telefono si è sempre caricato; il cavo vecchio era il problema'], 'Il primo è una deduzione: se le premesse sono vere, la conclusione è necessaria. Gli altri generalizzano da casi osservati.'),
      mc('Hai letto: «Le due uniche recensioni dicono che il ristorante è eccellente». La mossa più prudente è...', ['Notare che sono solo due casi e cercare altri dati prima di generalizzare', 'Concludere che è eccellente, perché due recensioni su due sono unanimità', 'Escludere il ristorante, perché poche recensioni sono già un segnale negativo', 'Fidarsi della recensione più lunga e ignorare del tutto l’altra'], 'Con due casi la regola è debole: la numerosità conta tanto quanto l’accordo.'),
      fill('Completa: una frase come «sicuramente l’ha fatto apposta» contiene un’___, non un fatto.', ['ipotesi', 'supposizione', 'interpretazione'], 'Attribuire un’intenzione è una spiegazione, non un’osservazione.'),
      fill('Completa: se un’ipotesi non può essere in nessun caso smentita, non è ___.', ['verificabile', 'controllabile', 'utile', 'falsificabile'], 'Un’ipotesi che non rischia nulla non ci insegna nulla.'),
      order('Metti in ordine i passi dell’indagine sul Wi-Fi', ['osservo', 'formulo ipotesi', 'scelgo un test', 'controllo il risultato'], 'Prima i fatti, poi le spiegazioni alternative, poi il test che le distingue, poi il confronto con il risultato.')
    ],
    test: [
      mc('Quale frase è una OPINIONE?', ['Questo ufficio è troppo rumoroso per lavorare bene', 'In ufficio la stampante è guasta dal mattino di ieri alle 10', 'Il rumore misurato in ufficio alle 11 è di 62 decibel', 'Al piano terra dell’ufficio lavorano in tutto 14 persone'], 'Il giudizio «troppo rumoroso» dipende da un criterio personale; le altre sono controllabili.'),
      mc('Hai visto un solo cliente lamentarsi del servizio e concludi «il servizio è pessimo». Quale errore stai commettendo?', ['Generalizzazione da un solo caso', 'Confusione tra correlazione e causa', 'Ancoraggio sul primo numero ricevuto', 'Errore nel calcolo delle frequenze naturali'], 'Un caso singolo non autorizza una regola generale.'),
      mc('Qual è la mossa migliore dopo aver formulato la prima ipotesi su un guasto?', ['Cercare un’ipotesi alternativa e un test che le distingua', 'Raccogliere soltanto le prove che confermano la prima ipotesi', 'Decidere subito la riparazione per risparmiare tempo prezioso', 'Chiedere a tutti i colleghi se sono d’accordo con la tua idea'], 'Una sola ipotesi spinge a cercare solo conferme.'),
      mc('Che cosa dimostra, e che cosa no, un esercizio simulato su questo argomento?', ['Dimostra che sai ragionare su casi dati; non prova come ti comporti nella vita reale', 'Dimostra che ragioni bene in ogni circostanza, anche sotto pressione o stanchezza', 'Dimostra che hai eliminato i bias di ragionamento e non ne soffri più', 'Dimostra che sai giudicare l’affidabilità di qualsiasi fonte in qualunque campo'], 'Un test su casi dati mostra una capacità in condizioni controllate: la prova reale richiede casi reali.'),
      fill('Completa: scrivere ciò che «vedrebbe una telecamera» serve a separare l’osservazione dall’___.', ['interpretazione', 'ipotesi', 'opinione'], 'L’osservazione descrive; l’interpretazione spiega.')
    ] });

  /* ================= DET · L1 ================= */
  T({ id: 'sma-det-l1-confronto-ipotesi-frequenze', pillar: 'det', stage: 'L1', title: 'Confrontare ipotesi e ragionare con le frequenze',
    summary: 'Una tabella evidenza-ipotesi per scegliere le prove che distinguono, e il metodo delle frequenze naturali per non sbagliare i primi problemi di probabilità.',
    objectives: ['Costruire una tabella evidenza-ipotesi e individuare la prova più diagnostica', 'Risolvere un problema di probabilità condizionata con le frequenze naturali', 'Spiegare perché un test «accurato» può dare molti falsi positivi quando la condizione è rara'],
    prereq: ['sma-det-l0-fatti-ipotesi-opinioni'], minutes: 20,
    pages: [
      { h: 'Dal sospetto alla tabella', b: `Nel livello precedente hai imparato a tenere in campo più ipotesi. Ora le **confrontiamo in modo ordinato**. Lo strumento più semplice è una tabella con le ipotesi in colonna e le prove in riga; in ogni cella segni se la prova è **coerente (C)**, **incoerente (I)** o **neutra (N)** con quell’ipotesi.\n\n> Problema: dopo l’aggiornamento di un’app il telefono si scarica in metà tempo. Ipotesi: H1 l’aggiornamento consuma di più; H2 la batteria è vecchia; H3 una funzione nuova resta attiva in background.\n> Prova A: la durata era normale fino a ieri sera. Prova B: nelle impostazioni, l’app risulta tra i maggiori consumi. Prova C: la batteria ha tre anni.\n\nTabella: A è incoerente con H2 (una batteria vecchia non peggiora di colpo in una notte), coerente con H1 e H3. B è coerente con H1 e H3, neutra per H2. C è coerente con H2 ma anche con tutto il resto: **non distingue**.` },
      { h: 'Prove che distinguono (diagnosticità)', b: `Una prova **coerente con tutte le ipotesi** non è informativa: non sposta nulla. Conta quanto la prova **cambia il rapporto** tra le ipotesi. Questo è il concetto di **diagnosticità**.\n\nChiediti per ogni prova: **«quanto sarebbe probabile vederla se H1 fosse vera, rispetto a se H2 fosse vera?»** Se la risposta è «circa uguale», la prova è poco diagnostica.\n\n> Un cliente dice: «Il pacco non è mai arrivato». Ipotesi: H1 il corriere l’ha perso; H2 il cliente non l’ha ritirato a casa del vicino. La frase «il pacco non è mai arrivato» è prevista da entrambe: non distingue. Il tracciamento «consegnato a persona diversa dal destinatario» invece è molto più probabile sotto H2.\n\nConseguenza pratica: cerca le prove **dove le ipotesi prevedono cose diverse**, non dove sono d’accordo. Una prova «a favore» di H1 che sarebbe stata uguale sotto H2 non è a favore di H1.` },
      { h: 'Il problema delle probabilità condizionate', b: `Quando una prova è soltanto probabilistica (un test, un allarme, un sintomo), il nostro intuito tende a confondere due domande diverse:\n\n- **P(positivo se hai la condizione)**: quanto il test «becca» i casi veri (sensibilità).\n- **P(hai la condizione se sei positivo)**: quanto puoi fidarti di un positivo.\n\nSono numeri diversi e la seconda dipende da **quanto è frequente la condizione** nella popolazione (la **prevalenza**, o probabilità di partenza). Ignorarla è l’errore detto **trascurare la probabilità di base**.\n\nUn metodo che evita quasi tutti gli errori è usare le **frequenze naturali**: invece di percentuali astratte, immagina **1000 persone** e conta quante cadono in ogni casella.` },
      { h: 'Caso svolto passo passo: un test di screening', b: `Valori **inventati a scopo didattico** (non sono dati di un test reale). Una condizione ha prevalenza **2%**. Un test la rileva nel **90%** dei casi veri (sensibilità) e dà un falso positivo nel **10%** delle persone senza la condizione. Una persona risulta positiva: quanto è probabile che abbia la condizione?\n\n**1. Prendi 1000 persone.** Con la condizione: 2% di 1000 = **20**. Senza: **980**.\n**2. Tra i 20 con la condizione**, il test è positivo per il 90%: 0,9 × 20 = **18 veri positivi**.\n**3. Tra i 980 senza**, il 10% è positivo: 0,1 × 980 = **98 falsi positivi**.\n**4. Totale dei positivi:** 18 + 98 = **116**.\n**5. Probabilità cercata:** 18 su 116 = 0,155, cioè circa **15,5%**.\n\n> Sorpresa: un test che «sbaglia solo nel 10%» lascia un positivo con meno di una probabilità su sei di avere davvero la condizione. I falsi positivi sono tanti perché i **sani sono molti di più**. Questo non dice che i test siano inutili: dice che un positivo va **confermato** con un secondo accertamento. Per le decisioni sanitarie reali rivolgiti sempre a un medico: qui è solo un esercizio di ragionamento.` },
      { h: 'Cambiare i numeri, cambiare la risposta', b: `Con le frequenze naturali si vede subito come reagisce il risultato. Stesso test (sensibilità 90%, falsi positivi 10%), ma prevalenza **1%**:\n\n- Su 1000: 10 con la condizione, 990 senza.\n- Veri positivi: 0,9 × 10 = **9**. Falsi positivi: 0,1 × 990 = **99**.\n- Probabilità: 9 su 108 = **circa 8,3%**.\n\nDimezzare la prevalenza ha più che dimezzato l’affidabilità del positivo. Se invece il test avesse solo il 5% di falsi positivi (prevalenza 1%, su 10 000 persone): 100 con la condizione, 90 veri positivi; 9900 senza, 495 falsi positivi; **90 su 585, cioè circa 15,4%**.\n\n> Stesso schema in altri ambiti: un filtro anti-spam che segnala 1 mail su 20 di quelle regolari come spam, applicato a una casella con quasi nessuno spam, produrrà più mail regolari bloccate che spam vero. Prima di fidarti di un «allarme», chiedi **quanto è frequente il fenomeno** che l’allarme cerca.` },
      { h: 'Confrontare alternative senza imbrogliare', b: `Alcune regole per un confronto onesto tra ipotesi:\n\n1. **Scrivi le ipotesi prima di guardare le prove**, non dopo: altrimenti tendi a formularle su misura.\n2. **Cerca le prove che potrebbero smentire** la tua preferita. Se non ne trovi, chiediti se hai guardato nel posto giusto.\n3. **Conta le prove per quello che distinguono**, non per quante sono. Dieci prove coerenti con tutte le ipotesi valgono come una.\n4. **Tieni separata la plausibilità iniziale** («quanto era probabile prima delle prove») dall’effetto delle prove. Un’ipotesi rara resta rara finché non arrivano prove forti.\n5. **Annota ciò che ancora non sai**: una cella «non so» non è un difetto, è un indicatore di dove cercare.\n\n> Esempio: «Il traffico del sito è calato del 30%». H1 errore di misurazione, H2 stagionalità, H3 calo di posizionamento. Prima prova da cercare: una che **distingua** (i dati del server mostrano lo stesso calo? l’anno scorso a questa data c’era un calo?).` },
      { h: 'Che cosa prova questo livello', b: `Se risolvi gli esercizi, hai mostrato di saper **usare le frequenze naturali** e **riconoscere una prova diagnostica** in casi con numeri dati. Non hai dimostrato di saper stimare da solo prevalenze e affidabilità in un caso reale: quei numeri nella vita reale vanno cercati in fonti attendibili, e spesso sono incerti. Quando non li hai, la mossa corretta è **dichiarare un intervallo** (per esempio «tra l’1% e il 5%») e vedere se la conclusione cambia.\n\nTre promemoria finali:\n- **Una prova non è una conclusione**: sposta le probabilità, non le azzera.\n- **Un test accurato su una condizione rara** produce molti falsi allarmi.\n- **La tabella è un aiuto, non un oracolo**: se i numeri nelle celle sono tuoi giudizi, la tabella ne eredita i limiti.` }
    ],
    exercises: [
      mc('In una tabella evidenza-ipotesi, una prova coerente con tutte le ipotesi è...', ['poco diagnostica: non aiuta a scegliere tra le ipotesi', 'molto diagnostica: conferma tutte le ipotesi in un colpo solo', 'una prova contraria che indebolisce tutte le ipotesi insieme', 'un fatto non verificabile che va tolto dalla tabella'], 'Se tutte le ipotesi la prevedono, non cambia il loro rapporto.'),
      mc('Un test ha sensibilità 90% e falsi positivi 10%, la condizione ha prevalenza 2%. Su 1000 persone quanti sono i falsi positivi?', ['98', '18', '116', '100'], '980 persone senza condizione × 10% = 98.'),
      mc('Con gli stessi dati, quale quota dei positivi ha davvero la condizione?', ['Circa 15,5%', 'Circa 90,0%', 'Circa 50,0%', 'Circa 2,00%'], '18 veri positivi su 116 positivi totali.'),
      mc('Se la prevalenza scende all’1% (stesso test: sensibilità 90%, falsi positivi 10%), che cosa succede alla quota di positivi veri?', ['Scende, perché i sani sono ancora più numerosi dei malati', 'Sale, perché con meno malati ci sono meno casi da confondere', 'Resta identica, perché sensibilità e falsi positivi non sono cambiati', 'Diventa del 90%, perché il test continua a rilevare il 90% dei casi'], 'Con prevalenza 1%: 9 veri su 108 positivi, circa 8,3%.'),
      mc('Un cliente scrive: «Il programma non parte». Ipotesi: H1 file corrotto, H2 aggiornamento mancante. Quale informazione è più diagnostica?', ['Il messaggio di errore indica una versione di libreria troppo vecchia', 'Il cliente è molto arrabbiato per il disservizio e lo ha scritto più volte', 'Il programma risulta usato da molti altri clienti senza problemi', 'Il cliente aveva già scritto al supporto un’altra volta il mese scorso'], 'Prevede cose diverse sotto H1 e H2; le altre sono coerenti con entrambe.'),
      mc('Quale comportamento è più scorretto nel confrontare ipotesi?', ['Cercare solo prove a favore della propria ipotesi preferita', 'Annotare le ipotesi prima di guardare i dati disponibili', 'Riconoscere che una cella della tabella resta «non so»', 'Distinguere probabilità iniziale ed effetto delle prove nuove'], 'Cercare solo conferme falsa il confronto.'),
      fill('Completa: su 1000 persone con prevalenza 1%, sensibilità 90% e falsi positivi 10%, i falsi positivi sono ___.', ['99'], '990 × 0,10 = 99.'),
      fill('Completa: con prevalenza 1%, sensibilità 90% e falsi positivi 5% su 10 000 persone, i positivi totali sono ___.', ['585'], '90 veri + 495 falsi = 585.'),
      order('Ordina il metodo delle frequenze naturali', ['prendo 1000 casi', 'divido per condizione', 'applico il test a ogni gruppo', 'confronto veri e totale positivi'], 'Dal campione immaginario alla quota di positivi veri.')
    ],
    test: [
      mc('Un test sulla stessa condizione ha prevalenza 5%, sensibilità 80%, falsi positivi 10%. Su 1000 persone quanti sono i positivi totali?', ['135', '145', '125', '130'], 'Veri: 0,8 × 50 = 40; falsi: 0,1 × 950 = 95; totale 135.'),
      mc('Con i dati del quesito precedente, quanti dei positivi sono veri positivi?', ['40 su 135', '40 su 50', '80 su 135', '95 su 135'], 'I veri positivi sono 40 e i positivi totali 135, circa 30%.'),
      mc('Un allarme «accurato al 99%» suona. Qual è la prima domanda da fare?', ['Quanto è frequente il fenomeno che l’allarme cerca?', 'Chi ha prodotto e venduto l’allarme che è appena suonato?', 'Da quanto tempo è installato l’allarme che sta suonando?', 'Quanto costerebbe sostituire l’allarme con uno più recente?'], 'Senza la probabilità di base l’accuratezza non dice quanto vale un positivo.'),
      mc('Che cosa non puoi concludere dagli esercizi con frequenze inventate?', ['Che i test reali abbiano quegli stessi valori', 'Che il metodo funzioni con altri numeri', 'Che i falsi positivi crescano con la quota di sani', 'Che un positivo richieda spesso conferma'], 'I numeri sono didattici: i valori reali vanno cercati in fonti affidabili.'),
      fill('Completa: la probabilità di partenza di una condizione nella popolazione si chiama ___.', ['prevalenza', 'probabilità di base', 'base rate'], 'È la frequenza della condizione prima del test.')
    ] });

  /* ================= DET · L2 ================= */
  T({ id: 'sma-det-l2-informazioni-incomplete-fonti', pillar: 'det', stage: 'L2', title: 'Informazioni incomplete e fonti',
    summary: 'Scegliere la prossima prova da cercare, aggiornare una stima con un rapporto di verosimiglianza e pesare l’affidabilità di una fonte.',
    objectives: ['Scegliere tra due test quello che riduce di più l’incertezza tra ipotesi concorrenti', 'Aggiornare una probabilità con il metodo delle quote (odds) e il rapporto di verosimiglianza', 'Valutare una fonte considerando sia quanto dice il vero sia quanto può dare falsi allarmi'],
    prereq: ['sma-det-l1-confronto-ipotesi-frequenze'], minutes: 20,
    pages: [
      { h: 'Decidere con ciò che non sai', b: `Quasi mai hai tutte le informazioni. Il punto non è aspettare di sapere tutto, ma **scegliere quale informazione cercare per prima**: quella che costa poco e cambia di più il quadro.\n\nIn pratica per ogni possibile prova chiediti tre cose:\n1. **Quali risultati può dare?**\n2. **Per ogni risultato, come si spostano le mie ipotesi?**\n3. **Che cosa farei diversamente in ciascun caso?** Se l’azione è identica qualunque sia l’esito, il test serve a poco, anche se è interessante.\n\n> Un amico ha ricevuto un SMS che dice di aver vinto un buono. Ipotesi: truffa, comunicazione vera dell’azienda. Cercare il numero sul sito ufficiale dell’azienda è un test utile: dà risposte diverse per le due ipotesi e cambia l’azione (ignorare / rispondere).\n> Leggere di nuovo il testo dell’SMS cinque volte non aggiunge nulla.` },
      { h: 'Aggiornare con le quote', b: `Il metodo delle frequenze naturali funziona benissimo, ma con più ipotesi e più prove serve uno strumento più compatto: le **quote (odds)** e il **rapporto di verosimiglianza (RV)**.\n\n- **Quota**: probabilità dell’ipotesi diviso probabilità del suo contrario. Probabilità 20% → quota 20/80 = 0,25 (cioè «1 a 4»).\n- **RV** = P(prova | H vera) diviso P(prova | H falsa). Se vale 3, la prova è tre volte più probabile se H è vera.\n- **Regola**: *quota dopo = quota prima × RV*.\n- Per tornare alla probabilità: p = quota / (1 + quota).\n\nQuando il RV è vicino a 1, la prova non conta. Quando è 10 o più, o 0,1 o meno, è forte.\n\n> Ricontrollo con le frequenze naturali del livello precedente (prevalenza 2%, sensibilità 90%, falsi positivi 10%): quota iniziale 0,02/0,98; RV = 0,9/0,1 = 9; quota dopo = 0,02/0,98 × 9 = 0,1837; p = 0,1837/1,1837 = 15,5%. È lo stesso risultato: due strade, un’unica verità.` },
      { h: 'Caso svolto: il caricabatterie', b: `Il telefono non si carica. Ipotesi e plausibilità iniziali (stime personali, da dichiarare come tali): **H1 cavo guasto 50%**, **H2 presa/alimentatore guasti 20%**, **H3 porta del telefono sporca o danneggiata 30%**.\n\nDue test possibili. **Test A: provo un altro cavo.** Se H1 è vera, con l’altro cavo carica con probabilità 0,90; se è vera H2 o H3, carica solo per caso (0,05).\n**Test B: provo un’altra presa.** Se H2 è vera, carica con 0,90; se H1 o H3, 0,05.\n\n**Calcolo Test A, esito «carica».** H1: 0,50 × 0,90 = 0,450. H2: 0,20 × 0,05 = 0,010. H3: 0,30 × 0,05 = 0,015. Totale 0,475. Posteriori: H1 = 0,450/0,475 = **94,7%**, H2 2,1%, H3 3,2%.\n**Esito «non carica»:** H1: 0,50 × 0,10 = 0,050. H2: 0,20 × 0,95 = 0,190. H3: 0,30 × 0,95 = 0,285. Totale 0,525. Posteriori: H1 9,5%, H2 36,2%, H3 54,3%.\n\n**Test B, esito «carica»:** probabilità totale 0,22; H2 diventa 81,8%.\n\nDecisione: poiché A può dare 94,7% su H1, e B ha una probabilità di successo più bassa (0,22 contro 0,475), A è il test migliore **qui**. Se i priori fossero diversi, la scelta potrebbe cambiare: i numeri sono giudizi, non misure.` },
      { h: 'Fonti: due domande distinte', b: `Una fonte (persona, giornale, sensore, app) non è «affidabile» o «inaffidabile» in assoluto. Servono almeno **due numeri**:\n\n- **Tasso di veri**: quante volte dice «sì» quando è vero.\n- **Tasso di falsi allarmi**: quante volte dice «sì» quando non è vero.\n\nIl rapporto tra i due è il RV della fonte. Una fonte che dice «sì» sempre ha tasso di veri 100% e falsi allarmi 100%: RV = 1, informazione zero.\n\n> Un collega che segnala «il server è giù» e ha ragione 8 volte su 10 quando il server è giù, ma lo dice anche 3 volte su 10 quando il server funziona: RV = 0,8/0,3 ≈ 2,7.\n\nCaso svolto: prima del messaggio ritieni il guasto poco probabile, **20%** (quota 0,25). Dopo il messaggio: quota 0,25 × 2,67 = 0,667; p = 0,667/1,667 = **40%**. Il messaggio ha raddoppiato la stima, ma non basta per dichiarare «è giù». Se un secondo collega, **realmente indipendente** dal primo, confermasse con la stessa affidabilità: quota 0,667 × 2,67 = 1,78; p = **64%**.` },
      { h: 'Quando le fonti non sono indipendenti', b: `Due conferme valgono doppio solo se **arrivano da canali diversi**. Se il secondo collega ha semplicemente letto il messaggio del primo, è la stessa informazione ripetuta: il RV complessivo resta circa 2,7, non 7,1.\n\nControlli rapidi per l’indipendenza:\n- **Da dove hanno saputo?** Se la risposta è «da lui», è una sola fonte.\n- **Potrebbero sbagliare per lo stesso motivo?** Due sensori vicini sullo stesso circuito possono guastarsi insieme.\n- **Hanno interesse comune?** Una recensione dell’azienda e una del suo partner commerciale non sono indipendenti.\n\n> Cinque siti riportano la stessa notizia con le stesse parole: probabilmente copiano da un unico comunicato. Cinque misure di giornalisti diversi che hanno visitato il luogo valgono molto di più.\n\nAnche l’**intenzione** conta: una fonte che ha qualcosa da guadagnare dalla tua convinzione può dire il vero, ma il suo tasso di falsi allarmi va stimato più alto.` },
      { h: 'Contraddizioni e lacune', b: `Quando due informazioni si contraddicono, la mossa sbagliata è scegliere quella che ti piace. La mossa giusta è chiedere **«in quale mondo sarebbero vere entrambe?»**\n\n> «Il negozio dice che l’ordine è partito lunedì. Il corriere dice che l’ha ritirato mercoledì.» Mondi possibili: il negozio ha registrato la partenza al momento dell’etichetta, non del ritiro; oppure il ritiro è stato un secondo tentativo; oppure uno dei due ha un errore di data. Ogni mondo suggerisce una verifica diversa (quale data riporta il tracciamento? c’è stato un primo tentativo?).\n\nCosì una contraddizione diventa **informazione**: dice che almeno una premessa va riesaminata.\n\nInfine, annota le **lacune**: ciò che non sai e che, se lo sapessi, cambierebbe la decisione. Una conclusione utile ha la forma: «Con quello che so la stima è 60%; mi cambierebbe il parere sapere X».\n\n**Limite di questo modulo.** Hai usato probabilità dichiarate nel testo. Nella vita reale non esiste un tasso di veri «stampato sulla fonte»: va stimato da esperienza e controlli, ed è spesso approssimato. L’esercizio prova che sai applicare la regola, non che le tue stime siano buone.` }
    ],
    exercises: [
      mc('Prima di scegliere quale test fare, quale domanda è più utile?', ['Che cosa farei diversamente a seconda dell’esito?', 'Quale test è più rapido da descrivere agli altri?', 'Quale test conferma meglio l’ipotesi che preferisco?', 'Quale test hanno usato altri in casi simili al mio?'], 'Un test che non cambia l’azione ha poco valore decisionale.'),
      mc('Probabilità 20%: qual è la quota (odds)?', ['0,25', '0,20', '4', '0,80'], '0,20/0,80 = 0,25.'),
      mc('Quota iniziale 0,25, RV = 4. Quale probabilità si ottiene?', ['50%', '25%', '80%', '100%'], '0,25 × 4 = 1; p = 1/2.'),
      mc('Una fonte dice «sì» nel 90% dei casi veri e nel 90% dei casi falsi. Qual è il suo RV e che cosa implica?', ['RV = 1: non porta alcuna informazione', 'RV = 90: è una fonte estremamente affidabile', 'RV = 0,9: è una fonte leggermente inaffidabile', 'RV = 2: raddoppia ogni volta la tua stima'], '0,9/0,9 = 1.'),
      mc('Nel caso del caricabatterie, l’esito «non carica» con il cavo nuovo porta H3 (porta del telefono) a circa...', ['54%', '30%', '10%', '5%'], '0,285 su un totale di 0,525.'),
      mc('Tre articoli identici riportano una notizia, tutti dalla stessa agenzia. Quante fonti indipendenti hai?', ['Una', 'Tre', 'Due', 'Nessuna'], 'Se derivano dalla stessa agenzia, la loro concordanza non è indipendente.'),
      mc('Quale NON è un buon modo di trattare una contraddizione tra due informazioni?', ['Tenere quella che conferma ciò che pensavo e scartare l’altra', 'Chiedersi in quale situazione potrebbero essere vere entrambe', 'Cercare la data o l’origine precisa di ciascuna informazione', 'Annotare quale verifica sposterebbe di più la tua stima finale'], 'Scegliere in base alla preferenza è il bias di conferma.'),
      fill('Completa: quota 0,25 × RV 2,67 dà una probabilità di circa ___ percento.', ['40'], '0,667/1,667 = 0,40.'),
      order('Ordina i passi per valutare un test da fare', ['elenco gli esiti possibili', 'stimo come cambiano le ipotesi', 'considero quale azione seguirebbe', 'scelgo il test più utile'], 'Dagli esiti alle conseguenze decisionali.')
    ],
    test: [
      mc('Il primo collega dice «il server è giù» (RV 2,67), prior 20%. Che cosa è sensato dire?', ['La stima sale al 40%: serve un’altra prova indipendente', 'È certo che il server sia giù, dato che lo dice un collega', 'Il messaggio non cambia nulla, perché potrebbe essere un errore', 'La stima scende al 10%, perché i colleghi sbagliano spesso'], 'La quota passa da 0,25 a 0,667: 40%.'),
      mc('Un secondo collega ripete il messaggio del primo perché l’ha letto in chat. Quale stima è più corretta?', ['Circa 40%: è la stessa informazione ripetuta', 'Circa 64%: due conferme indipendenti dello stesso guasto', 'Circa 80%: tre voci che dicono la stessa cosa', 'Circa 20%: le due conferme si annullano a vicenda'], 'Senza indipendenza non si moltiplica il RV.'),
      mc('Hai due test: A può dare 95% su un’ipotesi con probabilità di successo 0,5; B può dare 82% con probabilità 0,2. Quale conviene se costano uguale?', ['A, perché risolve più spesso e con più certezza', 'B, perché dà comunque una stima superiore all’80%', 'Sono equivalenti, perché costano la stessa cifra', 'Nessuno dei due: conviene prima raccogliere altri dati'], 'A risolve più spesso e con più certezza.'),
      mc('Che cosa non dimostra un esercizio con RV dichiarati nel testo?', ['Che sai stimare RV affidabili in una situazione reale', 'Che sai combinare quota e rapporto di verosimiglianza', 'Che sai riconoscere fonti che non sono indipendenti', 'Che sai scegliere il test più informativo tra due'], 'Nella vita reale i RV vanno stimati.'),
      fill('Completa: la regola di aggiornamento è: quota dopo = quota prima × ___.', ['rv', 'rapporto di verosimiglianza'], 'Il RV è il rapporto di verosimiglianza della prova.')
    ] });

  /* ================= DET · L3 ================= */
  T({ id: 'sma-det-l3-scenari-prove-dipendenti-bias', pillar: 'det', stage: 'L3', title: 'Scenari complessi: prove correlate, confondenti e inganni',
    summary: 'Aggiornare in più passi senza contare due volte la stessa informazione, riconoscere i fattori nascosti e ragionare quando una fonte può adattarsi o ingannare.',
    objectives: ['Aggiornare una probabilità in più passi con quote e RV, correggendo per la dipendenza tra prove', 'Riconoscere un fattore confondente confrontando i dati per sottogruppi', 'Distinguere le prove facili da falsificare da quelle costose da falsificare'],
    prereq: ['sma-det-l2-informazioni-incomplete-fonti'], minutes: 20,
    pages: [
      { h: 'Aggiornare in più passi', b: `Nei casi reali le prove arrivano **una dopo l’altra**. Lo schema resta quello del livello precedente: ogni prova moltiplica la quota per il suo RV, e il risultato diventa la quota di partenza per la prova successiva. Il vantaggio è che puoi **fermarti in qualsiasi momento** e sapere dove sei.\n\n> Caso svolto: un sistema segnala le transazioni sospette di una carta. Probabilità di partenza che una transazione sia fraudolenta: **10%** (quota 1/9 = 0,111).\n> Prova 1: la transazione avviene in un paese in cui il titolare non è mai stato. RV = 4 (quattro volte più probabile se è una frode). Quota: 0,111 × 4 = 0,444; probabilità = 0,444/1,444 = **30,8%**.\n> Prova 2: l’ora è insolita (le 4 di notte). RV = 3. Quota: 0,444 × 3 = 1,333; probabilità = 1,333/2,333 = **57,1%**.\n\nOgni passo è piccolo, controllabile, e **dichiara le sue assunzioni**: i due RV sono stime. Se qualcuno li contesta, la discussione verte su due numeri precisi, non su un vago «mi sembra sospetto».` },
      { h: 'Il doppio conteggio', b: `Il passo appena fatto ha un'assunzione nascosta: che le due prove siano **indipendenti** tra loro **una volta noto se c’è la frode**. Spesso non lo sono.\n\n> Il titolare è in viaggio all’estero (spiegazione innocente). Un viaggio all’estero rende insolito il paese **e** può rendere insolita l’ora (fuso orario). Le due prove sono quindi parzialmente la **stessa informazione** vista da due lati.\n\nSe il RV congiunto reale è, poniamo, 5 invece di 4 × 3 = 12, il risultato cambia: quota 0,111 × 5 = 0,556; probabilità = **35,7%** contro il 57,1% ottenuto contando due volte.\n\nLa differenza (57 contro 36) può decidere se bloccare una carta o chiedere una conferma al titolare. Per questo, quando combini prove, chiediti: **«se sapessi già la prima, la seconda mi direbbe ancora qualcosa di nuovo?»** Se la risposta è «poco», non moltiplicare i due RV per intero.\n\nRegola pratica: con prove forse correlate, **mostra due stime** (con e senza correlazione) e agisci in modo che la scelta regga a entrambe.` },
      { h: 'Il fattore nascosto', b: `A volte una relazione scompare, o si ribalta, quando guardi i dati **per sottogruppi**. Il motivo è un **fattore confondente**: qualcosa che influenza sia la causa presunta sia l’effetto.\n\n**Caso svolto con numeri.** Un team nota che chi usa la funzione «promemoria» di un’app resta iscritto più a lungo. Dati su 4000 utenti:\n\n- Con promemoria: 1000 utenti, 600 ancora iscritti dopo 3 mesi = **60%**.\n- Senza promemoria: 3000 utenti, 1100 ancora iscritti = **36,7%**.\n\nSembra un effetto enorme. Ora separiamo gli utenti in base a quanto erano già attivi nella prima settimana:\n\n- **Già molto attivi:** con promemoria 600 utenti, 480 restano (**80%**); senza promemoria 400 utenti, 320 restano (**80%**).\n- **Poco attivi:** con promemoria 400 utenti, 120 restano (**30%**); senza promemoria 2600 utenti, 780 restano (**30%**).\n\nDentro ogni gruppo la differenza è **zero**. I più attivi usano di più i promemoria **e** restano di più: il vero fattore era l’attività iniziale. Un confronto onesto richiede di confrontare **i simili con i simili**, o di assegnare la funzione a caso.\n\n**Cautela:** questa è un’analisi su numeri dati. Non prova che il promemoria sia inutile in assoluto (potrebbe aiutare in altri modi), prova solo che quel confronto grezzo non lo dimostra.` },
      { h: 'Prove facili e difficili da falsificare', b: `Se il mondo è passivo, una prova è quello che è. Se c’è qualcuno (o qualcosa) che ha interesse a **farti credere** una certa cosa, la prova può essere stata **prodotta apposta**. Non serve diventare paranoici: serve chiedersi **quanto costerebbe falsificare quella prova**.\n\n- **Facile da falsificare:** uno screenshot, un’email con firma testuale, una recensione, un «mi hanno detto».\n- **Più costosa da falsificare:** un documento ufficiale verificabile con l’emittente, un dato che si può ricontrollare in una fonte indipendente, un comportamento che richiede un reale sacrificio (pagare, esporsi, mantenere nel tempo).\n\n> Ricevi una mail che dice «sono il tuo istituto di credito, clicca qui». Il logo e il tono sono prove **a costo quasi zero**: chiunque le copia. Il fatto che sul sito ufficiale, aperto digitando tu l’indirizzo, compaia lo stesso avviso è una prova **più costosa da falsificare**.\n\nConseguenza: a prove **economiche da produrre** dai un RV vicino a 1 se l’altra parte ha un interesse a ingannarti; a prove costose dai un RV più alto.\n\nSe chi vuole ingannarti vede **quali controlli fai**, può adattarsi: un controllo prevedibile perde valore, per questo conviene verificare su un canale che l’altra parte non controlla (per esempio chiamare un numero ufficiale, non quello scritto nel messaggio).\n\nNota etica: queste tecniche servono a **difendersi dall’inganno e a non cadere in errore**. Usarle per costruire inganni non è l’obiettivo e va contro lo scopo del percorso.` },
      { h: 'I bias che disturbano l’analisi', b: `Anche con il metodo giusto, la testa ci mette lo zampino. Quattro bias che incidono sull’aggiornamento:\n\n1. **Conferma**: cerchi, ricordi e valuti meglio ciò che sostiene la tua idea. Rimedio: scrivere in anticipo **«che cosa mi farebbe cambiare idea?»**.\n2. **Ancoraggio**: il primo numero sentito pesa troppo. Rimedio: stimare **prima** di guardare il numero altrui.\n3. **Disponibilità**: giudichi frequente ciò che ti viene in mente facilmente (notizie recenti, storie vivide). Rimedio: cercare una frequenza, non un ricordo.\n4. **Retrospettiva**: dopo l’esito sembra che «era ovvio». Rimedio: annotare la **previsione prima**, con la sua probabilità.\n\n> Esempio: dopo un guasto improvviso del computer di lavoro, ti convinci che «dovevi saperlo». Se prima del guasto nessun segnale lo indicava, hai solo inventato a posteriori una storia coerente.\n\nI bias non si «spengono» con la volontà: si **riducono con procedure** (checklist, scrittura, confronto con base rate). Anche per questo ogni aggiornamento è meglio se è su carta.` },
      { h: 'Aggiornare né troppo né poco', b: `Due errori opposti:\n\n- **Reazione eccessiva**: un singolo episodio ribalta tutto. Una prova con RV 4 su una prior del 10% porta a 30,8%, non a «è sicuro».\n- **Conservatorismo**: le prove si accumulano e la stima non si muove perché «avevo già deciso».\n\nUna prova che **riduce** la probabilità funziona allo stesso modo con RV minore di 1. Se la transazione fosse invece avvenuta nel paese di residenza, in orario normale, con un acquisto abituale, il RV potrebbe essere 0,25: quota 0,111 × 0,25 = 0,0278, probabilità = **2,7%**.\n\nProcedura utile: dopo ogni prova scrivi **la nuova stima**, e verifica che il passaggio sia **proporzionato**: una prova debole sposta poco, una forte sposta molto. Se invece la tua stima salta di 40 punti con una prova che avresti definito «debole» prima di vederla, sospetta un bias.\n\nL’aggiornamento è anche un **dialogo con il costo dell’errore**: a parità di probabilità, il livello di prova richiesto per bloccare una carta (azione reversibile, costo basso) è diverso da quello per denunciare qualcuno (costo alto e non facilmente reversibile).` },
      { h: 'Rimettere insieme i pezzi e dichiarare i limiti', b: `Una buona analisi di scenario complesso ha, in forma breve, questa struttura:\n\n1. **Domanda** precisa («è una frode?», «il calo è reale?»).\n2. **Ipotesi** (incluse quelle innocenti) e **probabilità di partenza** motivate.\n3. **Prove**, ciascuna con **RV stimato** e nota su **indipendenza** e **costo di falsificazione**.\n4. **Aggiornamento** passo per passo, con stima finale e un **intervallo** («tra 36% e 57%»).\n5. **Decisione proporzionata** e **che cosa cambierebbe idea**.\n\n**Cosa prova questo modulo:** che sai applicare il metodo a casi dati, correggendo per dipendenze e confondenti. **Cosa non prova:** che le tue stime di RV, nei casi reali, siano ben tarate. La taratura si misura nel tempo, confrontando previsioni ed esiti: è il tema del livello L4.\n\n> Esercizio mentale da fare nella vita reale: la prossima volta che senti «tutti dicono che…», chiediti da quante fonti **indipendenti** viene, quanto costerebbe falsificarla, e se c’è un sottogruppo in cui il discorso non regge.` }
    ],
    exercises: [
      mc('Prior 10% (quota 0,111). Una prova con RV 4 e poi una con RV 3, supposte indipendenti: probabilità finale?', ['Circa 57%', 'Circa 31%', 'Circa 75%', 'Circa 40%'], '0,111 × 12 = 1,333; p = 0,571.'),
      mc('Se le due prove (RV 4 e RV 3) sono quasi la stessa informazione e il RV congiunto vale 5, la probabilità è...', ['Circa 36%', 'Circa 57%', 'Circa 20%', 'Circa 83%'], '0,111 × 5 = 0,556; p = 0,357.'),
      mc('Con promemoria 600 utenti su 1000 restano; senza promemoria 1100 su 3000. Dopo aver separato per attività iniziale, nei due gruppi la ritenzione è uguale tra chi usa e chi non usa il promemoria. Che cosa suggerisce?', ['Un confondente: l’attività iniziale spiega sia l’uso sia la permanenza', 'Che il promemoria funzioni molto, quindi va esteso a tutti gli utenti', 'Che i dati siano stati manipolati, perché la differenza sparisce', 'Che il campione sia troppo grande e quindi poco affidabile nei dettagli'], 'Dentro i sottogruppi la differenza sparisce.'),
      mc('Quale prova è più costosa da falsificare?', ['Un documento che l’emittente conferma con una verifica indipendente', 'Uno screenshot che mostra la conversazione con l’assistenza clienti', 'Un messaggio inoltrato da un conoscente che sembra ben informato', 'Una recensione completa di foto trovata su un sito di commenti'], 'Una conferma dall’emittente richiede di compromettere un canale che non controlli.'),
      mc('Prima di un esame prevedi «80% di superarlo». Dopo averlo superato dici «lo sapevo già». Quale bias è in gioco, se non avevi annotato nulla?', ['Retrospettiva: l’esito fa sembrare ovvio ciò che era incerto', 'Ancoraggio: ti sei fissato sul primo numero che avevi stimato', 'Disponibilità: ricordi con più facilità gli esami già superati', 'Conferma: hai cercato solo informazioni favorevoli al risultato'], 'Senza una previsione scritta si riscrive la storia a posteriori.'),
      mc('Quale NON è un rimedio ragionevole contro il bias di conferma?', ['Cercare solo informazioni dalle fonti che di solito danno ragione', 'Scrivere in anticipo che cosa mi farebbe cambiare la mia idea', 'Affidare a un collega la parte di chi contesta la conclusione', 'Cercare con impegno la prova più forte contro la propria ipotesi'], 'Scegliere fonti che confermano è proprio il bias.'),
      fill('Completa: prior 10% (quota 0,111), RV 0,25. La probabilità dopo la prova è circa ___ percento (arrotonda all’intero).', ['3'], '0,111 × 0,25 = 0,0278; p = 2,7%, arrotondato a 3.'),
      fill('Completa: quando una prova è quasi la stessa informazione di un’altra, i due RV non vanno moltiplicati per intero perché non sono ___.', ['indipendenti'], 'Il doppio conteggio richiede indipendenza.'),
      order('Ordina la struttura di un’analisi di scenario', ['domanda', 'ipotesi e prior', 'prove con RV', 'aggiornamento', 'decisione proporzionata'], 'Dalla domanda alla decisione, con un intervallo e le condizioni che cambierebbero idea.')
    ],
    test: [
      mc('Prior 20% (quota 0,25). Una prova con RV 6: probabilità finale?', ['60%', '30%', '75%', '45%'], '0,25 × 6 = 1,5; p = 1,5/2,5 = 0,6.'),
      mc('Quando due conferme provengono dalla stessa fonte originale, conviene...', ['Contarle come una sola informazione', 'Contarle come due, perché sono state ripetute', 'Contarle come tre, perché arrivano da più canali', 'Ignorarle entrambe, perché sono solo ripetizioni'], 'La ripetizione non è indipendenza.'),
      mc('Quale domanda aiuta a scoprire un confondente in un confronto tra gruppi?', ['I due gruppi erano simili in partenza, o scelti in modo diverso?', 'Quanti anni ha in media il campione che è stato analizzato?', 'Il risultato ottenuto ci piace o contraddice le nostre attese?', 'Il risultato è abbastanza sorprendente da finire in un titolo?'], 'Se i gruppi si sono formati in modo diverso, la differenza può nascere da quello.'),
      mc('Un’analisi dà una stima tra 36% e 57%. La conclusione più sensata è...', ['Scegliere un’azione che regga a entrambe le stime', 'Scegliere il numero più alto, per stare dalla parte della sicurezza', 'Fare la media delle due stime e non aggiungere altro', 'Rifiutarsi di decidere finché le stime non coincidono'], 'Una decisione robusta tiene conto dell’intervallo.'),
      fill('Completa: il bias per cui dopo l’esito sembra «era ovvio» si chiama bias della ___.', ['retrospettiva', 'retrospettiva', 'hindsight'], 'Annotare la previsione prima lo contrasta.')
    ] });

  /* ================= DET · L4 ================= */
  T({ id: 'sma-det-l4-previsioni-ed-esiti', pillar: 'det', stage: 'L4', title: 'Nella vita reale: previsioni scritte ed esiti',
    summary: 'Applicare il ragionamento a decisioni quotidiane con un registro di previsioni, un piccolo esperimento su di sé e il confronto onesto tra ciò che avevi stimato e ciò che è successo.',
    objectives: ['Scrivere una previsione verificabile con probabilità, data e criterio di esito', 'Calcolare il punteggio di Brier su un piccolo insieme di previsioni e leggere la calibrazione', 'Condurre e leggere con prudenza un confronto a giorni alterni su un’abitudine personale'],
    prereq: ['sma-det-l3-scenari-prove-dipendenti-bias'], minutes: 20,
    pages: [
      { h: 'Dove vale la pena applicarlo', b: `Fino a qui hai lavorato su casi dati. La differenza tra sapere un metodo e **usarlo** sta nell’averlo fatto su casi tuoi, con esiti che non controlli. Scegli decisioni quotidiane che soddisfano tre condizioni:\n\n1. **L’esito sarà osservabile** in tempi brevi (giorni o poche settimane).\n2. **C’è un margine di incertezza reale**, cioè non sai già com’è andata.\n3. **Sbagliare costa poco**: all’inizio meglio la scelta del ristorante che un investimento importante.\n\n> Esempi adatti: «Il pacco arriverà entro venerdì?», «Finirò il capitolo entro domenica?», «Il treno di ritorno avrà più di 10 minuti di ritardo?», «La riunione finirà entro le 11?», «Il nuovo aggiornamento risolverà il problema della batteria?».\n\n**Da evitare come esercizio:** diagnosi di salute (rivolgiti a un medico), decisioni che riguardano il giudizio su una persona precisa, scelte finanziarie rilevanti. Il percorso non sostituisce competenze professionali.` },
      { h: 'Il registro delle previsioni', b: `Un registro serve a **bloccare ciò che pensavi prima di sapere**. Ogni voce ha cinque campi:\n\n1. **Domanda** formulata in modo che la risposta sia sì/no.\n2. **Probabilità** (da 0 a 100%) che sia «sì».\n3. **Perché** in una riga: ipotesi principale e prova principale.\n4. **Criterio di esito**, scritto prima: che cosa conta come «sì».\n5. **Data di verifica.**\n\n> Esempio: «Entro venerdì alle 18 riceverò il pacco?» Probabilità 70%. Perché: il tracciamento dice «in consegna», ma il corriere precedente ha tardato due volte. Esito: «sì» se ricevo il pacco in mano mia o dal vicino entro le 18:00 di venerdì; il «tentativo di consegna» non conta. Verifica: venerdì alle 18:05.\n\nIl **criterio di esito** evita il problema di spostare i paletti a posteriori («in fondo il tentativo era come una consegna»). E la probabilità evita il «sapevo che sarebbe andata così»: se avevi scritto 70% e non è successo, non è una sconfitta, è un dato.\n\nBastano **3–5 previsioni a settimana**. Meglio poche fatte bene che molte lasciate a metà.` },
      { h: 'Cosa osservare mentre aspetti', b: `Tra previsione ed esito ci sono segnali che puoi annotare: sono i **segnali anticipatori**.\n\n> Previsione: «Finirò il capitolo entro domenica» (65%). Segnali da osservare: quante pagine alla fine di mercoledì? Se a metà settimana sei sotto il 30% del totale, il ritmo non basta. Annota il segnale e **aggiorna** la probabilità (per esempio 65% → 40%), senza cancellare la prima stima.\n\nPer ogni previsione definisci **un segnale e una soglia**: «se entro mercoledì sono a meno del 30%, scendo a 40%».\n\nCosì impari due cose diverse: se la previsione iniziale era buona, e se **l’aggiornamento in corso d’opera** è stato utile. Sono capacità diverse. Annotare entrambe le stime permette di distinguerle.\n\nAttenzione a **non osservare solo ciò che conferma**: se sei convinto che il pacco arriverà in tempo, tendi a notare i messaggi positivi e a trascurare quelli neutri.` },
      { h: 'Caso svolto: il punteggio di Brier', b: `Dopo qualche settimana hai cinque previsioni chiuse. Per misurare quanto sono state buone serve un numero che premi **sia l’aver azzeccato sia l’aver avuto la giusta fiducia**. Il **punteggio di Brier** è la media dei quadrati degli scarti tra la probabilità dichiarata p e l’esito (1 se è successo, 0 se no).\n\n- **A:** p = 0,8, esito 1, (0,8 − 1)² = 0,04
- **B:** p = 0,7, esito 1, (0,7 − 1)² = 0,09
- **C:** p = 0,6, esito 0, (0,6 − 0)² = 0,36
- **D:** p = 0,9, esito 1, (0,9 − 1)² = 0,01
- **E:** p = 0,3, esito 0, (0,3 − 0)² = 0,09

Somma = 0,59; media = **0,118**.\n\nConfronto utile: dire sempre 50% darebbe (0,5)² = **0,25** per ogni previsione, quindi 0,25 in media. Il tuo 0,118 è **migliore** di questo riferimento. Più basso è meglio: 0 è perfetto, 1 è il peggio (certezza sull’esito opposto).\n\nMa con **cinque** previsioni il punteggio oscilla molto: due esiti diversi basterebbero a cambiarlo. Prima di trarre conclusioni servono più dati, almeno qualche decina.` },
      { h: 'Calibrazione: la fiducia coincide con la frequenza?', b: `Il Brier mescola più cose. La **calibrazione** risponde a una domanda più precisa: **quando dici 70%, succede il 70% delle volte?**\n\nRaggruppa le previsioni per fascia (60–70%, 80–90%…) e confronta con la frequenza reale.\n\n> Hai fatto 10 previsioni al 70% e se ne sono avverate 7: sei perfettamente calibrato su quella fascia. Hai fatto 10 previsioni al 90% e se ne sono avverate 6: sei **troppo sicuro** (overconfidence) in quella fascia.\n\nAttenzione al **campione piccolo**: se 10 previsioni al 90% danno 8 avverate, non è automaticamente un problema; con 10 casi il caso conta molto. Per tirare conclusioni solide servono decine di previsioni per fascia.\n\nQuando sei sistematicamente troppo sicuro, rimedi pratici: **allarga gli intervalli**, evita 0% e 100%, e prima di dichiarare 90% chiediti «ho avuto esiti simili 9 volte su 10 in passato?»` },
      { h: 'Un piccolo esperimento su di te', b: `Puoi confrontare **due condizioni** alternando i giorni. Esempio: «Il caffè dopo le 16 ritarda il mio addormentamento?»\n\n**Disegno:** 14 giorni, 7 con caffè pomeridiano e 7 senza, **assegnati a caso** (moneta o sorteggio), per non farli coincidere con giorni particolari. Misura sempre la stessa cosa nello stesso modo: minuti stimati per addormentarsi.\n\n**Dati inventati, a scopo didattico:** con caffè 35, 40, 30, 45, 38, 32, 42 (media 37,4 minuti). Senza caffè 25, 30, 35, 20, 28, 32, 26 (media 28,0 minuti). Differenza **9,4 minuti**.\n\n**Lettura prudente:** le medie differiscono, ma gli intervalli si sovrappongono (30–45 contro 20–35) e il campione è di 14 giorni. È un **indizio**, non una prova. Altre cause possibili: allenamenti, stress, schermi serali. Dopo il primo ciclo puoi ripeterlo.\n\n**Limiti:** non è uno studio scientifico; non vale come consiglio medico; i problemi di sonno persistenti vanno visti da un professionista.` },
      { h: 'Errori nei propri ragionamenti (senza colpa)', b: `Ogni due settimane dedica 15 minuti a una revisione. Guarda le previsioni sbagliate e chiediti **non «chi ha colpa?» ma «dove si è rotto il ragionamento?»**\n\n- **Fatto o ipotesi?** Avevo dato per certo qualcosa che era una supposizione?\n- **Probabilità di base?** Avevo trascurato quanto è frequente quell’esito normalmente?\n- **Fonte?** Mi fidavo di una prova economica da falsificare?\n- **Bias?** Ho cercato solo conferme?\n- **Sfortuna?** Con una probabilità di 70% il 30% di volte va diversamente: **non ogni errore è un errore di ragionamento**.\n\nAttenzione all’**errore di esito**: giudicare la qualità di una decisione solo da com’è andata. Una buona decisione può avere un cattivo esito e viceversa.\n\n**Privacy ed etica:** non usare il registro per spiare o catalogare persone. Se la previsione riguarda altre persone, tieni solo ciò che è tuo da sapere.\n\n**Cosa prova questo livello:** solo l’uso reale nel tempo, con esiti che non controlli, mostra se il metodo funziona **per te**. Gli esercizi qui sotto ti allenano sul calcolo e sulla lettura dei risultati.` }
    ],
    exercises: [
      mc('Quale previsione è formulata meglio?', ['Riceverò il pacco entro venerdì alle 18: 70%', 'Il pacco arriverà presto: abbastanza probabile', 'Forse il pacco arriva, vedremo', 'Il corriere è inaffidabile'], 'Ha scadenza, probabilità e quindi un criterio di verifica.'),
      mc('Perché scrivere il criterio di esito prima?', ['Per non spostare i paletti dopo aver visto il risultato', 'Per rendere la previsione più lunga e più dettagliata', 'Per sembrare più sicuri di sé davanti a chi la legge', 'Per evitare di dover aggiornare la stima più avanti'], 'Senza criterio scritto è facile reinterpretare l’esito.'),
      mc('Una previsione al 60% non si avvera. Che cosa si può dire?', ['Non è per forza un errore: il 40% dei casi va così', 'Il ragionamento era per forza sbagliato in qualche punto', 'La probabilità reale era in verità dello 0 per cento', 'Non conta ai fini del registro, perché è un caso isolato'], 'Un esito contrario a 60% è atteso 4 volte su 10.'),
      mc('Il punteggio di Brier più basso indica...', ['Previsioni migliori', 'Previsioni peggiori', 'Più previsioni', 'Previsioni più sicure'], '0 è perfetto, 1 è il peggio.'),
      mc('Quale esperimento è meglio impostato?', ['Assegnare a caso 7 giorni con caffè e 7 senza, misurando sempre uguale', 'Provare una settimana con il caffè e poi una senza, notando come va', 'Notare soltanto le sere in cui ho dormito male e che cosa ho fatto', 'Chiedere a vari amici che cosa pensano degli effetti del caffè'], 'L’assegnazione casuale evita che le condizioni coincidano con giorni diversi per altri motivi.'),
      mc('10 previsioni al 90%, 6 avverate. L’interpretazione più prudente è...', ['Indizio di eccesso di fiducia, ma 10 casi sono pochi', 'Prova certa di eccesso di fiducia, già con 10 casi', 'Calibrazione perfetta, perché 6 su 10 è un buon risultato', 'Previsioni inutili, perché 10 casi non dicono nulla'], 'Con 10 casi il caso influisce molto: serve più campione.'),
      fill('Completa: previsione p = 0,2 con esito 1. Il quadrato dello scarto (p − esito)² vale ___.', ['0,64', '0.64'], '(0,2 − 1)² = 0,64.'),
      fill('Completa: sempre 50% dà un Brier di ___ per ogni previsione.', ['0,25', '0.25'], '(0,5)² = 0,25 qualunque sia l’esito.'),
      order('Ordina le voci del registro', ['domanda', 'probabilità', 'perché', 'criterio di esito', 'data di verifica'], 'Il criterio si scrive prima di conoscere l’esito.')
    ],
    test: [
      mc('Tre previsioni: (0,9; 1), (0,5; 0), (0,2; 0). Brier medio?', ['0,10', '0,25', '0,06', '0,33'], '(0,01 + 0,25 + 0,04)/3 = 0,10.'),
      mc('Che cos’è l’errore di esito?', ['Giudicare una decisione solo dal risultato ottenuto', 'Dichiarare probabilità troppo alte rispetto alle frequenze', 'Dimenticare di scrivere la data di verifica del registro', 'Usare troppi segnali anticipatori in una sola previsione'], 'Una buona decisione può dare un cattivo esito e viceversa.'),
      mc('Quale scelta NON è adatta come esercizio iniziale di previsione?', ['Stimare la probabilità di una malattia propria o altrui', 'Stimare se il pacco che aspetto arriverà entro venerdì sera', 'Stimare se finirò il capitolo che sto leggendo entro domenica', 'Stimare se la riunione di domani mattina finirà entro le 11'], 'Le valutazioni di salute spettano a un professionista.'),
      mc('Il confronto con 14 giorni mostra una differenza di 9,4 minuti con intervalli sovrapposti. La lettura giusta è...', ['Un indizio da verificare ancora, non una prova', 'Una prova definitiva del nesso causale tra caffè e sonno', 'Un risultato privo di qualsiasi informazione utile', 'Una conferma di tipo medico del problema del sonno'], 'Pochi giorni, intervalli sovrapposti: serve ripetere.'),
      fill('Completa: confrontare la fiducia dichiarata con la frequenza degli esiti si chiama ___.', ['calibrazione'], 'Calibrazione = dici 70% e succede il 70%.')
    ] });

  /* ================= DET · L5 ================= */
  T({ id: 'sma-det-l5-integrazione-problemi-aperti', pillar: 'det', stage: 'L5', title: 'Integrare i modelli su problemi aperti',
    summary: 'Combinare deduzione, probabilità, fonti e bias su un problema ambiguo, decidere con costi asimmetrici e correggere i propri metodi con evidenze ripetute.',
    objectives: ['Integrare più modelli su un caso ambiguo e dichiarare un’ipotesi residua «altro»', 'Fissare una soglia di azione dal rapporto tra i costi degli errori', 'Valutare con i numeri se una serie di previsioni indica davvero eccesso di fiducia'],
    prereq: ['sma-det-l4-previsioni-ed-esiti'], minutes: 20,
    pages: [
      { h: 'Un problema, molti strumenti', b: `Nei livelli precedenti ogni modulo ti ha dato uno strumento: la distinzione tra fatti e ipotesi, le frequenze naturali, le quote e i RV, le fonti, i bias, il registro delle previsioni. Un problema vero **non dichiara quale strumento serve**. A questo livello il compito è scegliere e combinare.\n\nUna sequenza di lavoro pratica:\n\n1. **Deduzione per restringere**: quali ipotesi sono incompatibili con fatti certi? Eliminale.\n2. **Probabilità per ordinare** le rimaste: prior motivati dalla frequenza di base.\n3. **Fonti per pesare** le prove: indipendenza, costo di falsificazione.\n4. **Bias per controllare** te stesso: che cosa mi farebbe cambiare idea?\n5. **Decisione** con costi degli errori.\n6. **Registrazione** per imparare.\n\n> Esempio: un reparto ha perso 3 giorni di dati di vendita. Ipotesi: errore umano nella procedura, guasto del software, aggiornamento che ha cambiato il formato, attacco informatico. Il log dice che la procedura non è stata eseguita: elimina «errore nella procedura» **solo se** il log è affidabile, e questo è già un punto da verificare.` },
      { h: 'L’ipotesi che non hai elencato', b: `Un errore classico di chi ragiona bene è elencare **tutte le ipotesi a cui ha pensato** e dividere il 100% fra esse. Ma se la spiegazione vera non è nell’elenco, tutte le probabilità sono gonfiate.\n\nSoluzione: aggiungi sempre un'ipotesi **«altro / non so»** con una probabilità residua, mai zero. Nei contesti nuovi può valere il 15–30%.\n\n> Caso svolto. Il traffico di un sito è calato del 30% in una settimana. Ipotesi e prior (giudizi motivati): H1 errore di misurazione 20%, H2 cambio di posizionamento sui motori di ricerca 25%, H3 guasto tecnico del sito 20%, H4 stagionalità 15%, **H5 altro 20%**. Prova: i dati del server mostrano un calo identico a quello dell’analisi. Questa prova è molto improbabile se H1 è vera (RV contro H1 circa 0,1) e neutra per le altre. Aggiornamento: H1 = 0,20 × 0,1 = 0,02; altre rimangono 0,25 + 0,20 + 0,15 + 0,20 = 0,80; totale 0,82. H1 scende a 2,4%; H2 = 0,25/0,82 = **30,5%**; H3 24,4%; H4 18,3%; H5 24,4%.\n\nNota che il risultato finale non conclude: restringe e indica dove cercare. **Una conclusione onesta di un problema aperto può essere «non lo so ancora, e so che cosa mi servirebbe».**` },
      { h: 'Decidere quando i costi degli errori sono diversi', b: `Raramente il costo di sbagliare in un senso è uguale a quello dell’altro. Chiama **C_FA** il costo di un falso allarme e **C_MISS** il costo di non agire quando serviva. Se agisci quando la probabilità che l’azione serva è p, il costo atteso è:\n\n- **Agire:** (1 − p) × C_FA\n- **Non agire:** p × C_MISS\n\nConviene agire quando p × C_MISS > (1 − p) × C_FA, cioè quando\n\n**p > C_FA / (C_FA + C_MISS).**\n\n> Caso svolto: un responsabile può fermare un servizio per una verifica. Fermarlo senza motivo (falso allarme) costa 1 unità (disagio di breve durata). Non fermarlo quando c’è un guasto reale costa 9 unità (perdita di dati). Soglia: 1/(1 + 9) = **10%**. Con una probabilità di guasto del 15% conviene fermarlo, anche se è «probabile che vada tutto bene».\n\nSe i costi fossero simmetrici (1 e 1) la soglia sarebbe 50%. Se il falso allarme costasse 9 e il mancato intervento 1, la soglia salirebbe al **90%**.\n\nLimite: i costi sono giudizi, non misure. Se la scelta cambia per costi plausibili diversi, la decisione è fragile e conviene raccogliere informazioni prima.` },
      { h: 'Autocorrezione: il ciclo', b: `Un metodo è buono se **si corregge**. Un ciclo semplice:\n\n1. **Prevedi** e registra (probabilità, criterio, data).\n2. **Osserva** i segnali e aggiorna, annotando le stime successive.\n3. **Chiudi** con l’esito, nel modo scritto in anticipo.\n4. **Analizza** i casi sbagliati: dove si è rotto il ragionamento? Quale categoria di errore?\n5. **Modifica una cosa sola** del metodo (una checklist, un’abitudine, una soglia).\n6. **Verifica nei cicli seguenti** se la modifica ha ridotto quella categoria di errore.\n\n> Esempio: nei tuoi registri vedi che sei sistematicamente troppo sicuro sulle scadenze di lavoro. Modifica: prima di scrivere una scadenza controlli quanto tempo hanno richiesto compiti simili. Nei due mesi seguenti, confronti la calibrazione.\n\nModificare **una cosa alla volta** serve a capire quale cambiamento ha funzionato. Se cambi cinque abitudini insieme e i risultati migliorano, non sai perché.\n\nAnche **chi ti fa da revisore** conta: una persona che legge il tuo ragionamento senza sapere cosa speri individua errori che tu non vedi. Se la scelta riguarda altre persone, spiegala in modo che possano contestarla.` },
      { h: 'Evidenze ripetute: quando i numeri bastano', b: `Hai registrato **20 previsioni al 80%**. Se la calibrazione fosse perfetta ne attenderesti circa 16 avverate. Ne sono avvenute **13**. Sei troppo sicuro?\n\n**Calcolo.** Se la vera probabilità fosse 80%, il numero di avverate ha media 16 e deviazione standard √(20 × 0,8 × 0,2) = **1,79**. Il 13 sta a (16 − 13)/1,79 ≈ **1,7 deviazioni standard** sotto la media. La probabilità di ottenere 13 o meno per puro caso, se la verità fosse 80%, è circa **8,7%**.\n\nQuindi: l’indizio c’è, ma **non è conclusivo**. Con una probabilità vicina al 9% di vedere un risultato così per caso, non puoi dire con tranquillità né «sono calibrato» né «sono troppo sicuro». La mossa corretta è **continuare a registrare**: con 40 previsioni e la stessa frequenza (65%), la prova sarebbe molto più chiara.\n\nCosa significa «evidenza ripetuta» in questo percorso: non basta un risultato buono in un esercizio. Conta ciò che **si ripete** in situazioni diverse, **senza aiuti**, **con esiti reali** e con **errori analizzati**.\n\nNessun numero rende «superiori»: un buon registro mostra che in certe situazioni ragioni in modo più **tarato** di prima, e il livello L5 è una descrizione di prestazioni misurate qui, non una patente di intelligenza o di infallibilità.` },
      { h: 'Obiettivi contrastanti e problemi nuovi', b: `A volte non c’è una risposta unica perché **gli obiettivi tirano in direzioni opposte**: velocità e accuratezza, riservatezza e trasparenza, costo e sicurezza. In questi casi il lavoro dell’analista è:\n\n1. **Esplicitare** gli obiettivi in conflitto e **chi li ha**.\n2. Mostrare **che cosa si perde** con ciascuna scelta, con numeri se disponibili.\n3. Proporre una scelta **e dire che cosa cambierebbe idea**.\n4. Segnare come **non risolto** ciò che i dati non permettono di decidere.\n\n> Esempio: un team deve decidere se pubblicare subito un avviso su un possibile difetto, con il 35% di probabilità che sia reale. Pubblicare subito protegge gli utenti ma può creare allarme; aspettare 48 ore riduce l’incertezza ma ritarda l’avviso. Qui nessuna formula decide: la soglia dipende da quanto è grave il danno potenziale e da quanto è reversibile un falso allarme (si può rettificare). Una soluzione ponderata è pubblicare un avviso **cauto** («stiamo verificando, nel frattempo fai X») invece di tacere o di affermare.\n\n**Etica.** In un problema aperto il rischio maggiore è usare l’incertezza per giustificare ciò che si voleva già fare. Chiediti sempre: **chi paga se sbaglio?** E: **sono disposto a spiegare questo ragionamento alle persone coinvolte?**\n\nIl percorso non ti promette capacità sovrumane: ti allena a ragionare con più ordine, a registrare i risultati e a correggerti nel tempo.` }
    ],
    exercises: [
      mc('Perché aggiungere un’ipotesi «altro» con probabilità residua?', ['Perché la spiegazione vera potrebbe non essere nell’elenco', 'Perché serve a far tornare a 100 la somma delle probabilità', 'Perché le altre ipotesi elencate sono quasi sempre sbagliate', 'Perché in questo modo il calcolo diventa molto più semplice'], 'Senza residuo si gonfiano le probabilità delle ipotesi elencate.'),
      mc('Nel caso del traffico, dopo la prova (RV 0,1 contro H1) la probabilità di H1 è circa...', ['2,4%', '20%', '10%', '0,2%'], '0,02/0,82 = 0,024.'),
      mc('Costo di falso allarme 1, costo di mancato intervento 9. Soglia d’azione?', ['10%', '90%', '50%', '9%'], '1/(1 + 9) = 0,10.'),
      mc('Con la soglia al 10% e una probabilità di guasto del 15%, che cosa conviene?', ['Agire: il costo atteso del non agire è più alto', 'Non agire: 15% è comunque sotto la metà dei casi', 'Raccogliere dati all’infinito finché non si ha certezza', 'Agire solo quando si è sicuri al 100% del guasto'], 'Non agire costa 0,15 × 9 = 1,35; agire costa 0,85 × 1 = 0,85.'),
      mc('20 previsioni all’80%, 13 avverate. Che cosa si può dire in modo corretto?', ['Indizio di eccesso di fiducia, non conclusivo: serve più campione', 'Prova certa di eccesso di fiducia, già con questi venti casi', 'Calibrazione perfetta, perché 13 su 20 è vicino alla media', 'Eccesso di prudenza: le previsioni erano troppo caute'], 'La probabilità di un risultato così o peggiore per caso è circa 8,7%.'),
      mc('Perché modificare una sola cosa alla volta nel proprio metodo?', ['Per capire quale cambiamento ha prodotto il miglioramento', 'Perché è molto più veloce che cambiare tutto insieme', 'Perché nessuno riesce davvero a cambiare due abitudini', 'Perché due modifiche insieme si annullano sempre a vicenda'], 'Con cambiamenti multipli non si distingue la causa del miglioramento.'),
      mc('Quale NON è un comportamento corretto in un problema aperto con obiettivi in conflitto?', ['Presentare l’incertezza come prova a favore della scelta già voluta', 'Dire con chiarezza che cosa cambierebbe la decisione finale', 'Segnalare apertamente ciò che resta non risolto dopo l’analisi', 'Mostrare che cosa si perde con ciascuna delle opzioni possibili'], 'Usare l’incertezza per giustificare ciò che si voleva già è il rischio etico principale.'),
      fill('Completa: soglia d’azione con costo del falso allarme 1 e del mancato intervento 3: ___ percento.', ['25'], '1/(1 + 3) = 0,25.'),
      order('Ordina il ciclo di autocorrezione', ['prevedi', 'osserva', 'chiudi con l’esito', 'analizza gli errori', 'modifica una cosa'], 'Il ciclo si chiude solo se l’analisi porta a una modifica verificabile.')
    ],
    test: [
      mc('Se i costi sono simmetrici (1 e 1), la soglia per agire è...', ['50%', '10%', '90%', '1%'], '1/(1 + 1) = 0,5.'),
      mc('Con costo del falso allarme 9 e del mancato intervento 1, la soglia è...', ['90%', '10%', '50%', '9%'], '9/(9 + 1) = 0,9.'),
      mc('Qual è il significato di «evidenza ripetuta» in questo percorso?', ['Risultati che si ripetono in contesti diversi, senza aiuti e con esiti reali', 'Un buon risultato ottenuto una sola volta in un singolo esercizio', 'Aver riletto più volte il modulo prima di rifare il test', 'Aver ottenuto lo stesso punteggio due volte di seguito nello stesso test'], 'Conta la ripetizione in condizioni diverse.'),
      mc('Che cosa non è il livello L5?', ['Una prova di intelligenza superiore o di infallibilità', 'Una descrizione di prestazioni misurate dentro questa app', 'Un invito a continuare a registrare previsioni ed esiti', 'Un livello che richiede anche un’applicazione nella realtà'], 'Il percorso descrive prestazioni, non promette capacità sovrumane.'),
      fill('Completa: in un problema aperto, quando non si può decidere dai dati, la conclusione onesta è dichiarare ciò che resta non ___.', ['risolto', 'noto', 'deciso'], 'Mostrare i limiti è parte dell’analisi.')
    ] });

  /* ================= PLN · L0 ================= */
  T({ id: 'sma-pln-l0-obiettivi-vincoli-conseguenze', pillar: 'pln', stage: 'L0', title: 'Obiettivi, vincoli e conseguenze',
    summary: 'Definire un obiettivo verificabile, elencare vincoli e risorse, stimare conseguenze probabili e riconoscere gli errori di pianificazione più semplici.',
    objectives: ['Trasformare un obiettivo vago in uno misurabile con scadenza', 'Distinguere vincoli fissi, vincoli negoziabili e risorse', 'Riconoscere errori semplici: solo il caso migliore, costi irrecuperabili, mezzi scambiati per fini'],
    minutes: 18,
    pages: [
      { h: 'Che cos’è un piano', b: `Un piano è una **risposta ordinata a cinque domande**:\n\n1. **Dove voglio arrivare?** (obiettivo)\n2. **Che cosa non posso cambiare, e che cosa ho a disposizione?** (vincoli e risorse)\n3. **Che cosa farò, in che ordine?** (azioni)\n4. **Che cosa succederà probabilmente dopo ogni azione?** (conseguenze)\n5. **Come saprò se sta funzionando?** (segnali di controllo)\n\nChi pianifica male di solito salta le domande 2 e 4: parte dall’azione («comincio a studiare!») senza sapere se ci sono i tempi, e senza chiedersi che cosa succederà se qualcosa va storto.\n\n> Piano debole: «Questo mese metto da parte dei soldi».\n> Piano più solido: «Entro il 30 del mese metto da parte 120 euro, spostandoli sul conto di risparmio il giorno dello stipendio. Se a metà mese le spese sono già sopra il previsto, riduco il resto, non l’accantonamento».\n\nNel secondo caso si capisce **che cosa fare, quando e come controllare**.` },
      { h: 'Obiettivi che si possono verificare', b: `Un obiettivo vago («stare meglio con i soldi», «andare bene all’università») non permette di decidere né di controllare. Un obiettivo utile ha quattro parti:\n\n- **Risultato**: che cosa sarà diverso.\n- **Misura**: come lo vedrò (un numero, un sì/no osservabile).\n- **Scadenza**: entro quando.\n- **Motivo**: perché lo voglio, che serve a scegliere tra mezzi alternativi.\n\n> Vago: «Voglio organizzarmi meglio con lo studio». Verificabile: «Entro il 15 giugno ho ripassato i 12 capitoli di Storia, 1 capitolo ogni 2 giorni, e ho fatto 2 simulazioni di esame con almeno 60% di risposte corrette».\n> Vago: «Voglio mangiare meglio». Verificabile: «Per 4 settimane cucino a casa almeno 5 cene su 7 e le segno nel quaderno» (un obiettivo di abitudine, non una prescrizione dietetica: per la salute vera sentiremmo un professionista).\n\nAttenzione a **non confondere mezzi e fini**: «comprare un’agenda nuova» è un mezzo; il fine è ricordarsi le scadenze. Se il mezzo non funziona, cambiane un altro, non insistere.` },
      { h: 'Vincoli e risorse', b: `**Vincoli**: ciò che limita le scelte. **Risorse**: ciò che puoi usare.\n\nTipi di vincoli:\n- **Fissi**: non cambiano nel tuo orizzonte (una data d’esame, l’orario di apertura di un ufficio, le regole di un contratto).\n- **Negoziabili**: si possono spostare con un costo (una scadenza interna, una riunione, un budget).\n- **Autoimposti**: regole che ti sei dato e che puoi rivedere.\n\nRisorse tipiche: **tempo, denaro, energia, competenze, aiuto di altri, strumenti**. Una risorsa spesso trascurata è l’**energia**: sei lucido alla mattina e a pezzi alle 22? Il piano deve tenerne conto.\n\n> Un viaggio di 3 giorni. Vincoli fissi: il treno parte il 14 alle 7:10, la prenotazione dell’alloggio non è rimborsabile. Negoziabile: il budget per i pasti. Risorse: 600 euro, due giorni di ferie, un amico che conosce la città.\n\nElencare i vincoli **prima** dei dettagli evita il piano bellissimo e impossibile.` },
      { h: 'Caso svolto: preparare un esame', b: `Obiettivo: prepararsi a un esame su un testo di **240 pagine**, tra 12 giorni. Vincolo fisso: la data. Risorsa: puoi dedicare una sessione al giorno.\n\n**Passo 1, buffer.** Tieni 2 giorni liberi per ripasso e imprevisti: restano **10 giorni** di lavoro.\n**Passo 2, ritmo.** 240 ÷ 10 = **24 pagine al giorno**.\n**Passo 3, segnale di controllo.** Dopo 4 giorni dovresti essere a 4 × 24 = **96 pagine**.\n\n**Imprevisto.** Dopo 4 giorni sei a **80 pagine**, 16 in meno. Restano 160 pagine e 6 giorni di lavoro (più 2 di buffer).\n\nOpzioni:\n- **Recuperare senza buffer:** 160 ÷ 6 ≈ **26,7 pagine al giorno** (un po’ più del piano, ma sostenibile).\n- **Usare il buffer come giorni di studio:** 160 ÷ 8 = **20 pagine al giorno**, ma senza giorni di scorta.\n- **Rivedere il perimetro:** chiedere se alcuni capitoli sono meno importanti per l’esame (negoziare il vincolo, se è possibile).\n\n> La scelta dipende da quanta fiducia hai nel ritmo e da quanto ti costa non avere margine. Il valore del caso è l’aver **visto la deviazione presto**, grazie al segnale dei 96 pagine, e aver deciso con numeri invece che con ansia.` },
      { h: 'Probabilità e conseguenze', b: `Ogni azione ha **esiti possibili**, ciascuno con una certa probabilità e un certo peso. Anche senza calcoli precisi, ragionare così migliora le scelte.\n\nTi serve rispondere a due domande per ogni rischio:\n- **Quanto è probabile?** (rara, possibile, probabile)\n- **Quanto è grave, e si può rimediare?**\n\n> Esempi di scelta con ombrello. Se piove con probabilità 30% e arrivare bagnati ti costa pochissimo (hai un cambio in ufficio), puoi lasciarlo. Se hai un colloquio e arrivare bagnati ti danneggia, lo porti anche con 30%.\n\nLa stessa probabilità porta a decisioni diverse perché cambia **la gravità** e **la reversibilità**. Un errore recuperabile (dimenticare una password, che si reimposta) è molto diverso da uno non recuperabile (cancellare l’unica copia di un documento).\n\nPer le cose irrecuperabili conviene un passo preventivo (**copia di sicurezza**), per le recuperabili conviene decidere in fretta.` },
      { h: 'Errori semplici di pianificazione', b: `**1. Pianificare solo il caso migliore.** Ogni attività «dura 2 ore se tutto va bene». Pianifica un margine per l’attrito reale.\n\n**2. Dimenticare un vincolo.** «Faccio tutto il sabato» dimenticando che sabato hai un impegno in famiglia.\n\n**3. Costi irrecuperabili.** «Ho già speso 80 euro in questo corso, quindi devo finirlo». Il denaro già speso non si recupera in alcun caso: conta solo **quanto vale continuare da adesso**.\n\n**4. Mezzi scambiati per fini.** Passare ore a ordinare gli appunti con colori diversi senza aver mai ripassato.\n\n**5. Obiettivo senza controllo.** Se non c’è un segnale a metà strada, ti accorgi dello scarto solo alla scadenza.\n\n**6. Piano che richiede forza di volontà infinita.** Se funziona solo se sei sempre in forma, non è un piano.\n\n> Esempio di costo irrecuperabile: hai pagato un abbonamento annuale a un’app di lingue ma dopo tre mesi non la apri più. Il pagamento è un fatto del passato: la domanda utile è «dedicherò davvero tempo a questa app, o un’alternativa mi serve meglio da ora?»` },
      { h: 'Che cosa prova questo livello', b: `Gli esercizi ti dicono se, **dato un caso scritto**, sai separare obiettivo, vincoli e risorse, fare un calcolo di ritmo e riconoscere un errore classico. Non dicono se **tu** riesci a sostenere un piano per settimane, perché per questo servono giorni veri, imprevisti veri e un controllo.\n\nPer cominciare nella vita reale: scegli **un solo obiettivo piccolo** con scadenza entro due settimane, scrivi le quattro parti (risultato, misura, scadenza, motivo), elenca due vincoli e un segnale di controllo a metà strada. Nei livelli successivi imparerai a confrontare alternative e a prevedere le reazioni degli altri.\n\n**Etica minima.** Un buon piano non richiede di ingannare, forzare o danneggiare altri per funzionare. Se per raggiungere l’obiettivo servirebbe nascondere qualcosa a qualcuno che ne sarebbe danneggiato, quello è un segnale per **rivedere l’obiettivo**, non per migliorare l’inganno.` }
    ],
    exercises: [
      mc('Quale obiettivo è verificabile?', ['Entro il 20 marzo avrò scritto 3 pagine della relazione, in 3 sessioni', 'Voglio scrivere molto meglio la relazione e con più calma', 'Mi impegnerò molto sulla relazione in tutti i prossimi giorni', 'Cercherò di fare buoni progressi sulla relazione di studio'], 'Ha risultato, misura e scadenza.'),
      mc('La data di un esame è per te...', ['Un vincolo fisso', 'Un vincolo negoziabile se sei in ritardo', 'Una risorsa', 'Un’opinione'], 'Non puoi spostarla nel tuo orizzonte di pianificazione.'),
      mc('Hai 300 pagine e 15 giorni, 3 di buffer. Quante pagine al giorno sui giorni di lavoro?', ['25', '20', '30', '15'], '15 − 3 = 12 giorni; 300 ÷ 12 = 25.'),
      mc('Hai pagato un corso non rimborsabile e ora ti accorgi che non ti serve. Che cosa conta per decidere se continuare?', ['Il valore che avrà continuare da ora in poi', 'Quanto hai già speso per iscriverti al corso', 'Che cosa penseranno gli altri se lo abbandoni', 'La durata complessiva del corso fino alla fine'], 'I costi passati sono irrecuperabili in entrambe le scelte.'),
      mc('Quale caso richiede più cautela, a parità di probabilità 20%?', ['Un errore che cancellerebbe l’unica copia di un documento', 'Un errore che ti fa perdere cinque minuti di lavoro oggi', 'Un errore che si corregge subito con un clic sul pulsante', 'Un errore che si rimedia con una breve telefonata al servizio'], 'La gravità e la reversibilità cambiano la decisione.'),
      mc('Quale NON è un errore di pianificazione descritto nel modulo?', ['Prevedere un margine per gli imprevisti', 'Pianificare solo il caso migliore possibile', 'Dimenticare un vincolo che era già noto', 'Scambiare un mezzo per il fine che si vuole raggiungere'], 'Il margine è una buona pratica, non un errore.'),
      fill('Completa: 240 pagine in 10 giorni di lavoro sono ___ pagine al giorno.', ['24'], '240 ÷ 10 = 24.'),
      fill('Completa: 160 pagine da recuperare in 8 giorni sono ___ pagine al giorno.', ['20'], '160 ÷ 8 = 20.'),
      order('Ordina le domande di un piano', ['obiettivo', 'vincoli e risorse', 'azioni', 'conseguenze', 'segnali di controllo'], 'Dalla meta al controllo.')
    ],
    test: [
      mc('Dopo 4 giorni, a 24 pagine al giorno, dovresti essere a...', ['96 pagine', '80 pagine', '100 pagine', '120 pagine'], '4 × 24 = 96.'),
      mc('Quale azione trasforma meglio un obiettivo vago in uno utile?', ['Aggiungere una misura osservabile e una scadenza', 'Aggiungere una frase motivazionale in apertura', 'Rimandare la scadenza per avere più tempo', 'Scrivere l’obiettivo in stampatello su un foglio'], 'Misura e scadenza rendono verificabile l’obiettivo.'),
      mc('Quale esempio descrive un mezzo scambiato per un fine?', ['Passare ore a colorare gli appunti senza mai ripassare', 'Studiare un capitolo al giorno secondo il calendario', 'Fare un controllo a metà strada sul ritmo di lavoro', 'Prevedere una sessione di recupero prima della scadenza'], 'Il colore degli appunti è un mezzo, il fine è imparare.'),
      mc('Che cosa prova un esercizio simulato di pianificazione?', ['Che sai applicare il metodo a casi dati; il piano reale richiede giorni reali', 'Che riesci a rispettare qualunque piano ti venga proposto', 'Che non avrai imprevisti nei tuoi progetti di studio', 'Che hai il controllo completo sulle scadenze degli altri'], 'La tenuta nel tempo si vede solo con applicazione reale.'),
      fill('Completa: un vincolo che non cambia nel tuo orizzonte, come la data d’esame, è un vincolo ___.', ['fisso'], 'I vincoli fissi non si negoziano.')
    ] });

  /* ================= PLN · L1 ================= */
  T({ id: 'sma-pln-l1-alberi-decisionali', pillar: 'pln', stage: 'L1', title: 'Alberi decisionali e confronto di alternative',
    summary: 'Disegnare le scelte come albero, stimare il valore atteso, controllare quanto la scelta dipende dalle stime e giustificarla in poche righe.',
    objectives: ['Costruire un albero con nodi di scelta, nodi di caso ed esiti', 'Calcolare e confrontare i valori attesi e verificarne la sensibilità alle stime', 'Giustificare una decisione semplice indicando rischi e che cosa la farebbe cambiare'],
    prereq: ['sma-pln-l0-obiettivi-vincoli-conseguenze'], minutes: 20,
    pages: [
      { h: 'Disegnare la scelta', b: `Un **albero decisionale** rappresenta una scelta come ramificazione:\n\n- **Nodo di scelta** (quadrato): decidi tu.\n- **Nodo di caso** (cerchio): decide il mondo, con probabilità.\n- **Esito** (foglia): il risultato finale con un valore.\n\nNel testo lo scriviamo a elenco:\n\n> Scelta: come consegnare una tesina.\n> - **A: lavoro da solo.** Caso: in tempo (70%) → voto 28; in ritardo (30%) → voto 22.\n> - **B: chiedo una revisione prima.** Caso: in tempo (90%) → voto 27; in ritardo (10%) → voto 22.\n\nPerché disegnarlo? Perché mostra **che cosa non hai ancora considerato** (e se il caso «in ritardo» ha davvero lo stesso voto in A e in B), e ti obbliga a mettere numeri e probabilità, anche approssimati, su ciò che prima era un sentimento.\n\nUna regola: **ogni scelta deve avere almeno due rami** e i casi di un nodo devono coprire tutte le possibilità (le probabilità sommano a 100%).` },
      { h: 'Il valore atteso', b: `Il **valore atteso (VA)** di un nodo di caso è la media dei valori degli esiti, **pesata per le probabilità**: VA = somma di (probabilità × valore).\n\n**Caso svolto, la tesina:**\n- VA(A) = 0,7 × 28 + 0,3 × 22 = 19,6 + 6,6 = **26,2**.\n- VA(B) = 0,9 × 27 + 0,1 × 22 = 24,3 + 2,2 = **26,5**.\n\nIn media B è meglio di **0,3 punti**. Una differenza piccola: la decisione non è chiara come sembrava a prima vista.\n\n**Cosa non dice il VA:**\n- è una media su molte ripetizioni ipotetiche, mentre tu fai **una sola** scelta;\n- non include **il costo** delle opzioni (B costa 2 giorni di lavoro);\n- non distingue tra un esito che puoi sopportare e uno che non puoi.\n\n> Se i due giorni di B valgono per te più di 0,3 punti di voto, il vantaggio sparisce e A torna alla pari o in vantaggio. Il VA ti dice **di quanto** vince un’opzione, e quel «di quanto» va confrontato con i costi che il VA non include.` },
      { h: 'Quanto dipendono dalle stime? La sensibilità', b: `Le probabilità dell’albero sono **tue stime**. La domanda decisiva è: **quanto dovrebbero cambiare per far cambiare la scelta?**\n\nNell’esempio, se A avesse probabilità p di consegna in tempo:\nVA(A) = 22 + 6p.\nVA(A) eguaglia VA(B) = 26,5 quando 22 + 6p = 26,5, cioè **p = 0,75**.\n\nQuindi: se sei sicuro che da solo consegni in tempo **almeno 75% delle volte**, A è alla pari o meglio. Se pensi 70%, B è leggermente meglio. La stima 70% o 75% è difficile da distinguere: **la scelta è «aperta»** e conviene usare altri criteri (il costo, il rischio, l’opportunità di imparare).\n\nIn pratica:\n1. Trova il **punto di pareggio**.\n2. Chiediti: **«sono più sicuro di essere sopra o sotto?»**\n3. Se sei lontano dal pareggio, la scelta è robusta. Se sei vicino, non fidarti troppo del calcolo.\n\nQuesto è il motivo per cui un albero non «decide»: **mostra dove sta la decisione**.` },
      { h: 'Confronto con più criteri', b: `Non tutto si riduce a un numero. Quando i criteri sono più d’uno (costo, tempo, rischio, quanto imparo) è utile una **tabella semplice**:\n\n> Viaggio di ritorno, due opzioni.\n> - **Treno:** costo 45 euro; probabilità 10% di ritardo superiore a un’ora, costo del ritardo 40 euro (taxi o pasto).\n> - **Auto:** costo 70 euro (carburante e pedaggio); probabilità 5% di traffico grave, costo 30 euro (tempo e carburante).\n> VA costo: treno 45 + 0,1 × 40 = **49 euro**; auto 70 + 0,05 × 30 = **71,5 euro**.\n\nIl treno è più economico di oltre 22 euro. Ma se arrivare puntuale è un **vincolo fisso** (un colloquio alle 9) e un ritardo di un’ora è inaccettabile, la domanda cambia: non è più «quale costa meno», ma «quale ha **meno probabilità di violare il vincolo**» (10% contro 5% per ritardo grave). Qui l’auto riduce il rischio, a un costo di 22,5 euro in più: sei disposto a pagare quel prezzo per dimezzare la probabilità di un ritardo grave?\n\nUna regola utile: **prima eliminare le opzioni che violano i vincoli, poi confrontare le restanti**.` },
      { h: 'Rischi, mitigazioni e opzioni reversibili', b: `Per ogni ramo importante chiediti: **che cosa può andare storto, e posso ridurre il danno?**\n\n- **Mitigazione**: un’azione che riduce probabilità o gravità (partire prima, avere una copia, chiedere conferma).\n- **Opzione reversibile**: una scelta da cui puoi tornare indietro. Se due opzioni hanno VA simili, preferisci quella **reversibile**: lascia aperta la porta mentre impari di più.\n- **Opzione informativa**: una scelta che costa poco e ti dà informazioni utili per la scelta grande (una prova, un colloquio, un piccolo test).\n\n> Esempio: stai decidendo se comprare un abbonamento annuale a un servizio. Alternativa reversibile: il mese di prova o il pagamento mensile, che costa un po’ di più ma ti lascia uscire. Se la tua probabilità di usarlo davvero è molto incerta (50%), il piccolo costo extra compra **informazione e libertà**.\n\nAlcuni errori non si recuperano; per quelli vale la regola di pensarci di più. Altri sono piccoli e reversibili: decidere in fretta e correggere è meglio che rimandare indefinitamente.` },
      { h: 'Giustificare una decisione in quattro righe', b: `Una decisione ben giustificata si può riassumere così:\n\n1. **Obiettivo e vincoli** (che cosa voglio, che cosa non posso violare).\n2. **Alternative** considerate (almeno due, e una «non fare nulla» quando ha senso).\n3. **Stime chiave** e **punto di pareggio**.\n4. **Rischio principale** e **che cosa mi farebbe cambiare idea**.\n\n> Esempio: «Obiettivo: consegnare la tesina in tempo con voto ≥ 26. Vincolo: scadenza 20. Alternative: A da solo, B con revisione (2 giorni). Stime: A 70% in tempo, B 90%; VA 26,2 contro 26,5; il pareggio è al 75%. Scelgo B perché la mia stima di A è più vicina a 70% e preferisco ridurre il rischio. Cambierei idea se scoprissi che il revisore non è disponibile prima del 16.»\n\nOra puoi **mostrarlo** a qualcuno e farlo contestare: è il vantaggio di avere un ragionamento scritto.\n\n**Cosa prova questo livello:** sai costruire e leggere un albero con numeri dati. Nella vita le probabilità sono stime incerte, per cui conta di più il controllo di sensibilità che l’ultima cifra del valore atteso. Per scelte importanti (salute, lavoro, soldi) usa gli alberi per **organizzare il pensiero**, non per sostituire un professionista.` }
    ],
    exercises: [
      mc('In un albero, il nodo di caso (cerchio) rappresenta...', ['Un evento che non controlli, con probabilità', 'Una scelta che prendi tu tra le opzioni', 'Un obiettivo finale da raggiungere entro la scadenza', 'Un vincolo fisso che non puoi modificare in alcun modo'], 'I nodi di caso sono decisi dal mondo.'),
      mc('Opzione X: 60% di guadagnare 100, 40% di guadagnare 20. Valore atteso?', ['68', '60', '70', '80'], '0,6 × 100 + 0,4 × 20 = 60 + 8 = 68.'),
      mc('Opzione Y: guadagno certo di 65. Con X (VA 68), che cosa si può dire?', ['X vince di poco in media, ma Y è senza rischio: va pesato', 'Y vince sempre perché un guadagno certo è meglio di una media', 'X vince di molto, quindi la scelta è del tutto evidente', 'Sono equivalenti, perché la differenza è solo di 3 punti'], 'Una differenza di 3 punti non copre per forza il rischio.'),
      mc('Con VA(A) = 22 + 6p e VA(B) = 26,5, per quale p le due opzioni si equivalgono?', ['0,75', '0,70', '0,80', '0,90'], '6p = 4,5, p = 0,75.'),
      mc('Se il punto di pareggio è 75% e la tua stima è 40%, che cosa suggerisce?', ['La scelta è robusta: la stima è molto lontana dal pareggio', 'La scelta è ancora molto aperta, perché ogni stima è incerta', 'Il calcolo è sicuramente sbagliato, perché 40 è inferiore a 75', 'Bisogna lanciare una moneta perché non si può decidere nulla'], 'Più la stima è lontana dal pareggio, più la scelta è stabile.'),
      mc('Quale è un vincolo fisso nella scelta tra treno e auto?', ['Dover arrivare prima delle 9 a un colloquio', 'Preferire il treno perché permette di leggere', 'Il prezzo del carburante, che può variare di settimana', 'La voglia di leggere durante il viaggio di ritorno'], 'Un vincolo fisso esclude le opzioni che non lo soddisfano.'),
      fill('Completa: treno 45 + 0,1 × 40 = ___ euro di costo atteso.', ['49'], '45 + 4 = 49.'),
      fill('Completa: se due opzioni hanno VA simile, conviene preferire quella ___.', ['reversibile'], 'Una scelta reversibile lascia aperta la porta.'),
      order('Ordina la giustificazione di una decisione', ['obiettivo e vincoli', 'alternative', 'stime e pareggio', 'rischio e cosa cambia idea'], 'Dalla meta al criterio di revisione.')
    ],
    test: [
      mc('Opzione P: 50% di +80, 50% di −20. Valore atteso?', ['30', '60', '50', '20'], '0,5 × 80 + 0,5 × (−20) = 40 − 10 = 30.'),
      mc('Quando A e B hanno valore atteso vicino, che cosa conviene valutare in più?', ['Reversibilità, rischio principale e costi non inclusi nel VA', 'Quale delle due è più elegante da disegnare come albero', 'Quale delle due piace a un maggior numero di persone', 'Quale delle due ha più rami e quindi più dettagli'], 'Il VA non include costi, reversibilità e tollerabilità del rischio.'),
      mc('Che cosa significa «opzione informativa»?', ['Una scelta poco costosa che dà dati per la decisione più grande', 'Una scelta già presa e comunicata a tutte le persone coinvolte', 'Una scelta senza alcun rischio e senza costi di nessun genere', 'Una scelta che serve soprattutto a informare altre persone'], 'Serve a ridurre l’incertezza prima di impegnarsi.'),
      mc('Che cosa non prova un esercizio con probabilità date?', ['Che le tue stime reali di probabilità siano ben tarate', 'Che sai calcolare il valore atteso di ciascuna opzione', 'Che sai trovare un punto di pareggio tra due opzioni', 'Che sai leggere e costruire un albero decisionale'], 'Nella vita le probabilità vanno stimate e possono essere sbagliate.'),
      fill('Completa: nell’albero, le probabilità dei rami di un nodo di caso sommano a ___ percento.', ['100'], 'I casi devono coprire tutte le possibilità.')
    ] });

  /* ================= PLN · L2 ================= */
  T({ id: 'sma-pln-l2-mosse-incentivi-reazioni', pillar: 'pln', stage: 'L2', title: 'Più mosse, incentivi e reazioni degli altri',
    summary: 'Ragionare all’indietro su un albero con più giocatori, capire perché gli incentivi spiegano i comportamenti e progettare accordi leciti che li allineano.',
    objectives: ['Applicare il ragionamento all’indietro a un gioco sequenziale a due giocatori', 'Spiegare un comportamento a partire dagli incentivi e proporre una modifica lecita', 'Scegliere con informazioni incomplete usando una soglia di probabilità'],
    prereq: ['sma-pln-l1-alberi-decisionali'], minutes: 20,
    pages: [
      { h: 'Quando contano le mosse degli altri', b: `Finora il «caso» era la natura: il meteo, un ritardo. Con altre persone il mondo **reagisce a ciò che fai**, e spesso ha propri obiettivi. Un piano a più mosse deve quindi includere una domanda in più: **«e dopo la mia mossa, che cosa converrà fare all’altro?»**\n\nNon serve supporre che l’altro sia freddo e calcolatore; basta chiedersi **che cosa ci guadagna o perde** da ciascuna scelta. Il comportamento degli altri è spesso meglio spiegato dai loro incentivi che dai loro caratteri.\n\n> Un collega non risponde alle email del tuo team. Spiegazione per carattere: «è maleducato». Spiegazione per incentivi: «il suo obiettivo del trimestre è chiudere 20 pratiche, e rispondere a noi non conta nelle pratiche». La seconda suggerisce una soluzione (mettere la richiesta tra le sue priorità condivise con il responsabile), la prima solo un giudizio.\n\nAttenzione: l’incentivo spiega, **non giustifica**. Capire perché qualcuno si comporta male non significa approvarlo.` },
      { h: 'Il ragionamento all’indietro', b: `In un gioco a turni, per capire che cosa succede conviene partire **dalla fine**. Si chiama **ragionamento all’indietro** (backward induction):\n\n1. Scrivi tutte le mosse finali e i **payoff** (cosa ottiene ciascuno).\n2. Chi muove per ultimo sceglie ciò che **gli conviene di più**.\n3. Il giocatore precedente **prevede** quella scelta e sceglie di conseguenza.\n4. Risali fino alla prima mossa.\n\n**Caso svolto: il lavoro affidato a un esterno.** Tu (A) devi decidere se **affidare** un lavoro a un fornitore (B) o **non affidarlo** e fare da solo.\n- Non affidi: payoff (4 per te, 4 per B).\n- Affidi, e B fa un lavoro **buono**: (8 per te, 5 per B).\n- Affidi, e B fa un lavoro **scadente**: (2 per te, 7 per B), perché B risparmia fatica e tempo.\n\n**Ultima mossa (B):** 7 > 5 → B sceglie **scadente**.\n**Prima mossa (A):** se affidi, ti aspetti 2; se non affidi, 4. Quindi **non affidi**.\n\nRisultato: (4, 4), **peggiore per entrambi** del possibile (8, 5). Nessuno è «cattivo»: è la struttura degli incentivi.` },
      { h: 'Cambiare gli incentivi, non le persone', b: `Nel caso precedente il problema è che **a B conviene tradire**. Invece di sperare che B sia buono, puoi **cambiare le regole del gioco in modo trasparente e consensuale**:\n\n- **Garanzia o penale concordata:** se il lavoro è scadente, B rimborsa 4. Nuovi payoff con lavoro scadente: (2 + 4 = 6 per te, 7 − 4 = 3 per B).\n- **Ultima mossa (B):** buono = 5, scadente = 3. B sceglie **buono**.\n- **Prima mossa (A):** affidare dà 8, non affidare 4. Affidi.\n\nRisultato: (8, 5), **meglio per entrambi**.\n\nAltri modi leciti di allineare gli incentivi: **pagamento a milestone**, **recensioni pubbliche**, **rapporti ripetuti** (B ha interesse a mantenere una buona reputazione se lavorerete ancora insieme), **trasparenza** su criteri e controlli.\n\n> Un limite da sapere: un incentivo mal progettato produce effetti non voluti. Se premi un team in base al **numero di ticket chiusi**, qualcuno spezzetterà un problema in cinque ticket per chiudere più ticket. L’incentivo ha fatto esattamente ciò che chiedevi, non ciò che volevi.\n\n**Etica:** gli accordi devono essere **dichiarati e accettati**. Un incentivo nascosto per costringere o ingannare l’altro non è pianificazione, è manipolazione.` },
      { h: 'Informazioni incomplete: di chi mi sto fidando?', b: `Nel caso del fornitore, spesso **non sai che tipo di fornitore sia B**. Se è **affidabile** farà sempre un lavoro buono; se non lo è, scadente. Supponi che la probabilità che B sia affidabile sia **p**.\n\nSe affidi (senza garanzie): VA = p × 8 + (1 − p) × 2 = 2 + 6p. Non affidare dà 4.\nAffidi quando 2 + 6p > 4, cioè **p > 1/3**.\n\n- Se la tua stima di p è 20%: VA = 3,2 < 4 → non affidi.\n- Se è 50%: VA = 5 > 4 → affidi.\n\nQuesta soglia ti dice **quanta fiducia serve** per agire. E ti dice che cosa vale la pena fare prima: **raccogliere informazioni** (referenze, un piccolo lavoro di prova) che spostino p. Un lavoro di prova a basso costo può valere più di un lungo ragionamento.\n\nNota la differenza tra **fiducia** e **speranza**: la fiducia ha una base osservabile (storia, referenze, controlli), la speranza no.` },
      { h: 'Reazioni a catena e più variabili', b: `Quando ci sono più persone e più variabili, il ragionamento all’indietro diventa lungo. Non serve risolvere tutto: usa uno schema di tre passi.\n\n1. **Elenca gli attori** che possono reagire e **che cosa vogliono**.\n2. **Per ogni tua mossa, scrivi la reazione più probabile** (e quella più dannosa).\n3. **Rivaluta la tua mossa** dopo la reazione: è ancora conveniente?\n\n> Esempio: vuoi spostare la riunione di squadra dal lunedì al venerdì. Attori: i colleghi (chi lavora part-time il venerdì), il responsabile (che ha un’altra riunione), il cliente (che aspetta un aggiornamento il lunedì). Reazione più probabile: i part-time non potranno esserci. Reazione dannosa: il cliente riceve l’aggiornamento una settimana dopo. La mossa sembra semplice, ma con le reazioni diventa costosa.\n\nA volte la mossa migliore è **domandare** prima di agire: un messaggio breve («spostare a venerdì crea problemi a qualcuno?») fa emergere gli incentivi che non vedi. **Chiedere non è un segno di debolezza: è raccogliere informazioni.**` },
      { h: 'Pianificare almeno due mosse avanti', b: `Un piano migliora molto con un solo esercizio in più: **per ogni mossa, scrivi le due mosse successive dell’altro**. Non per prevedere il futuro, ma per smettere di trattare l’altro come un elemento passivo.\n\n> Esempio: stai per proporre a un fornitore uno sconto in cambio di un ordine più grande. **Mossa tua:** proponi il 10% di sconto sul doppio dell’ordine. **Reazione 1 possibile:** accetta. **Reazione 2:** contropropone il 6%. **Reazione 3:** rifiuta ma offre consegna gratuita. Per ciascuna, **la tua risposta**.\n\nIl valore del metodo sta nell’**essere preparati**: non devi sapere quale reazione avverrà, devi aver pensato a una risposta ragionevole per ciascuna.\n\n**Che cosa prova questo livello.** Hai applicato il ragionamento all’indietro a esempi con payoff dati. Nei casi reali i payoff sono incerti, le persone sono più varie e i giochi non sono mai così puliti: usa questi modelli per **fare domande migliori**, non per prevedere con certezza. Inoltre, ciò che ti serve per **proteggere un accordo** (garanzie, trasparenza, reputazione) è sempre da usare con il consenso delle parti: non c’è nessuna «strategia» che giustifichi ingannare o costringere.` }
    ],
    exercises: [
      mc('Nel gioco del fornitore (senza garanzie), che cosa sceglie B se affidi?', ['Lavoro scadente: 7 è più di 5', 'Lavoro buono: 5 è un payoff accettabile', 'Dipende dal tuo carattere', 'Non può scegliere'], 'B massimizza il proprio payoff.'),
      mc('Perché A decide di non affidare?', ['Prevede un lavoro scadente da B: 2 per sé contro 4 se non affida', 'Perché 4 è il payoff massimo che può ottenere in assoluto', 'Perché è un pessimista e diffida di qualsiasi fornitore', 'Perché B muove per primo e A può soltanto adeguarsi'], 'A ragiona all’indietro dalla scelta di B.'),
      mc('Con una penale concordata di 4 su B in caso di lavoro scadente, i payoff di B diventano buono 5, scadente...', ['3', '7', '1', '5'], '7 − 4 = 3.'),
      mc('Quale intervento NON è un modo lecito di allineare gli incentivi?', ['Nascondere al fornitore le conseguenze per spingerlo a scegliere come vuoi', 'Pagamenti a milestone concordati e comunicati a entrambe le parti', 'Recensioni pubbliche su cui entrambe le parti sono informate', 'Garanzie scritte accettate da entrambe le parti prima del lavoro'], 'Gli accordi devono essere dichiarati e accettati.'),
      mc('Perché un premio per «numero di ticket chiusi» può produrre ticket spezzettati?', ['L’incentivo premia il numero, non il valore del lavoro', 'Perché le persone sono sempre disoneste quando c’è un premio', 'Perché il sistema dei ticket è troppo lento da usare', 'Perché i ticket originali sono quasi sempre troppo grandi'], 'Un indicatore troppo semplice viene ottimizzato in modo non voluto.'),
      mc('Senza garanzie, A affida se la probabilità che B sia affidabile supera...', ['1/3', '1/2', '2/3', '1/4'], '2 + 6p > 4 → p > 1/3.'),
      fill('Completa: con p = 0,5 il valore atteso dell’affidare (2 + 6p) è ___.', ['5'], '2 + 3 = 5.'),
      fill('Completa: il ragionamento che parte dalla mossa finale e risale si chiama ragionamento all’___.', ['indietro'], 'In inglese: backward induction.'),
      order('Ordina i passi del ragionamento all’indietro', ['scrivo gli esiti finali', 'l’ultimo giocatore sceglie', 'il precedente lo prevede', 'risalgo alla prima mossa'], 'Dalla fine all’inizio.')
    ],
    test: [
      mc('Con p = 0,2, vale la pena affidare senza garanzie?', ['No: il VA è 3,2 contro 4', 'Sì: 0,2 è una probabilità positiva', 'Sì: il VA è 5', 'Dipende dalla simpatia'], '2 + 6 × 0,2 = 3,2 < 4.'),
      mc('Un collega ignora le tue richieste. Quale spiegazione è più utile per agire?', ['Non è tra i suoi obiettivi: conviene capire che cosa gli conta', 'È fatto così per carattere e non c’è molto da capire', 'Lo fa apposta per metterti in difficoltà con gli altri', 'Non gli importa di nessuno e quindi nemmeno del team'], 'Gli incentivi suggeriscono un’azione, il giudizio sul carattere no.'),
      mc('Perché un lavoro di prova a basso costo può essere una buona mossa?', ['Sposta la stima di affidabilità con un costo ridotto', 'Perché è sempre gratuito per chi lo propone e per chi lo fa', 'Perché elimina completamente ogni rischio di lavoro scadente', 'Perché risolve da solo il problema degli incentivi'], 'Produce informazione utile prima dell’impegno grande.'),
      mc('Che cosa non prova un esercizio con payoff dati?', ['Che nei casi reali conosci i payoff degli altri', 'Che sai ragionare all’indietro su un gioco a turni', 'Che sai valutare una soglia di probabilità per agire', 'Che sai leggere l’effetto di una modifica degli incentivi'], 'I payoff reali sono incerti.'),
      fill('Completa: gli incentivi di un accordo vanno dichiarati e ___ da tutte le parti.', ['accettati', 'condivisi', 'concordati'], 'Altrimenti è manipolazione.')
    ] });

  /* ================= PLN · L3 ================= */
  T({ id: 'sma-pln-l3-conseguenze-avversari-contingenze', pillar: 'pln', stage: 'L3', title: 'Conseguenze indirette, avversari adattivi e piani A/B/C',
    summary: 'Seguire le conseguenze di secondo e terzo ordine, ragionare quando l’altra parte si adatta, gestire risorse limitate e scrivere piani contingenti con soglie di cambio.',
    objectives: ['Seguire una catena di conseguenze e stimarne la plausibilità a ogni anello', 'Leggere una matrice di esiti quando l’altra parte può reagire alla tua mossa', 'Scrivere un piano A/B/C con una soglia numerica di passaggio e una riserva di risorse'],
    prereq: ['sma-pln-l2-mosse-incentivi-reazioni'], minutes: 20,
    pages: [
      { h: 'Conseguenze di primo, secondo e terzo ordine', b: `Una conseguenza **di primo ordine** è l’effetto diretto e immediato di una mossa. **Di secondo ordine** è ciò che accade perché gli altri e il sistema reagiscono al primo effetto. **Di terzo ordine** è ciò che cambia a lungo andare per le abitudini, i comportamenti e le attese che si formano.\n\n> Un negozio online abbassa il prezzo di un prodotto da 50 a 40 euro (costo 30 euro; vendite attuali 100 pezzi al mese, utile 2000 euro).\n> - **1° ordine:** vendite in aumento. Supponiamo salgano a 160 pezzi.\n> - **2° ordine:** il concorrente nota il calo e abbassa il suo prezzo.\n> - **3° ordine:** i clienti si abituano a comprare solo in sconto e il prezzo di 50 euro non è più credibile.\n\nIl primo ordine sembra un successo. Con 160 pezzi a 10 euro di margine: **1600 euro** di utile, **meno** dei 2000 di partenza. Per pareggiare servirebbero 2000 ÷ 10 = **200 pezzi**, cioè il doppio delle vendite. L’aumento di vendite non era la domanda giusta: la domanda era se l’**utile** cresceva.\n\nUna buona abitudine: dopo aver scritto l’effetto di primo ordine, ripeti «**e poi?**» almeno altre due volte.` },
      { h: 'Non inventare catene infinite', b: `«E poi?» può diventare una macchina per costruire scenari immaginari. Per evitarlo, attribuisci a **ogni anello** una probabilità approssimativa e un grado di gravità.\n\n> Catena: sconto → il concorrente reagisce (70%) → guerra di prezzi (50% se il concorrente reagisce) → margini erosi per tutti. Probabilità dell’intera catena, assumendo che gli anelli dipendano l’uno dall’altro: 0,7 × 0,5 = **35%**.\n\nLa probabilità di una catena è il **prodotto** delle probabilità condizionate degli anelli: più sono lunghe, più la probabilità scende. Ma la gravità può crescere, quindi una catena al 35% con danno grave merita attenzione, mentre una al 2% con danno lieve no.\n\nRegola pratica: **scrivi le catene che superano una soglia** (per esempio probabilità > 10% o danno non recuperabile) e **ignora le altre**, con la consapevolezza che stai scegliendo di ignorarle.\n\nSe rimani vago («potrebbe succedere di tutto»), non stai pianificando, stai sentendo ansia. Se numeri e nomini le catene, puoi decidere **quali** vale la pena prevenire.` },
      { h: 'Avversari che si adattano', b: `Una persona o un’organizzazione che osserva ciò che fai **cambia comportamento**. Per questo non basta stimare una probabilità fissa: **la probabilità dipende dalla tua mossa**.\n\n**Caso svolto, ancora lo sconto.** Hai due mosse: **sconto** o **mantieni** il prezzo. Il concorrente ha due mosse: **abbassa** o **mantiene**. Utili mensili (in euro, ipotesi didattiche):\n\n- Sconto, il concorrente mantiene: **2600**.\n- Sconto, il concorrente abbassa: **1000**.\n- Mantieni, il concorrente mantiene: **2000**.\n- Mantieni, il concorrente abbassa: **1400**.\n\n**Se il concorrente non reagisce a te** e abbassa con probabilità q: VA(sconto) = 2600 − 1600q; VA(mantieni) = 2000 − 600q. Sono uguali per **q = 0,6**: lo sconto conviene solo se pensi che il concorrente abbassi **meno del 60%** delle volte.\n\n**Se il concorrente reagisce**, la tua mossa cambia il suo comportamento: se tu fai lo sconto, lui probabilmente abbassa. Allora il confronto non è 2600 contro 2000, ma **1000** (sconto, lui abbassa) contro **2000** (mantieni, lui mantiene). Con un avversario adattivo, la mossa che sembrava migliore diventa la peggiore.\n\n**Mossa prudente:** guardare il caso peggiore di ogni riga. Sconto: minimo 1000. Mantieni: minimo 1400. Il «caso peggiore migliore» è **mantenere**.` },
      { h: 'Risorse limitate e riserve', b: `Un piano con risorse limitate (tempo, denaro, energia, attenzione) deve stabilire **dove investire** e **quanto tenere in riserva**.\n\nRegole pratiche:\n1. **Riserva per gli imprevisti**: per progetti nuovi, il 15–20% delle risorse (se hai dati su progetti simili, usali).\n2. **Non concentrare tutto su una sola ipotesi** quando l’incertezza è alta: investire per gradi (prima una parte, poi altro se i segnali sono buoni).\n3. **Distingui costi che puoi sospendere** da costi già impegnati.\n4. **Decidi in anticipo che cosa non farai**: le risorse limitate sono anche un elenco di rinunce.\n\n> Esempio: un budget di 3000 euro per far conoscere una piccola attività. Riserva del 20% = 600 euro, restano **2400** da allocare. Invece di spenderne subito 2400 in annunci, ne spendi **900** nella prima settimana, osservi i risultati e poi decidi. Se funziona, investi altro; se non funziona, i 1500 rimasti più la riserva permettono di cambiare approccio.\n\nUna riserva non è «soldi sprecati»: è il prezzo per poter reagire senza essere costretti a smettere.` },
      { h: 'Piani A, B e C con soglie', b: `Un **piano contingente** dice **che cosa fare se**. Ha tre parti:\n\n- **Piano A:** il percorso principale.\n- **Segnale e soglia:** un indicatore misurabile e il valore che fa scattare il cambio.\n- **Piano B (e C):** l’alternativa già preparata, con il costo del passaggio.\n\n**Caso svolto: la campagna di iscrizioni.** Budget 3000 euro. Riserva 600. Piano A: annunci per 2 settimane (900 nella prima, 900 nella seconda). **Segnale:** costo per iscritto dopo la prima settimana. **Soglia:** se supera 12 euro, si passa al piano B.\n\nDopo 7 giorni: spesi 900, **60 iscritti**. Costo per iscritto = 900 ÷ 60 = **15 euro**. Superata la soglia → **piano B:** invece di altri 900 in annunci, spendi 700 per migliorare la pagina di iscrizione e 400 per annunci più mirati.\n**Piano C** (se anche B non funziona entro la terza settimana): sospendi gli annunci e usi la riserva per parlare con 10 persone che non si sono iscritte e capire perché.\n\nIl valore sta nell’aver deciso **la soglia prima**, quando sei lucido, e non quando sei già coinvolto o ansioso. E nell’aver **limitato il costo di cambiare**: i passi sono piccoli e reversibili.\n\nAttenzione al «c’è sempre un Piano B» come consolazione: un Piano B non provato è un’ipotesi, non un piano.` },
      { h: 'Verificare che la soglia sia ragionevole', b: `Una soglia troppo sensibile ti fa cambiare ogni giorno; una troppo tollerante ti fa insistere sul piano sbagliato. Tre controlli:\n\n1. **Quanta variabilità normale c’è?** Se il costo per iscritto oscilla tra 9 e 15 nei giorni buoni, una soglia di 12 scatta per caso. Meglio una media su più giorni.\n2. **Quanto costa cambiare?** Se il cambio è economico e reversibile, soglia più sensibile; se è costoso, serve più evidenza.\n3. **Che cosa vedresti se il Piano A funzionasse?** Descrivilo prima, in numeri.\n\n> Esempio: nei 7 giorni le iscrizioni sono 8, 9, 7, 10, 12, 8, 6 (media 8,6 al giorno, totale 60). Un solo giorno a 6 non è un segnale; l’intera media che porta il costo a 15 euro invece lo è.\n\nQuesto è anche il modo per **evitare l’inganno di sé**: spostare la soglia dopo aver visto i dati è un modo per mantenere il piano che già preferisci.\n\n**Cosa prova il modulo.** Hai usato numeri dati per seguire catene e leggere matrici. Nei casi reali le probabilità e gli utili sono incerti e gli avversari non sono quasi mai razionali in modo puro: usa i modelli per **vedere le mosse alternative**, non per prevederle con sicurezza. E ricorda il limite etico: pianificare **contro** un avversario significa prepararsi alle sue mosse legittime, non imbrogliarlo o danneggiarlo.` }
    ],
    exercises: [
      mc('Sconto da 50 a 40 con costo 30 e 160 pezzi: utile mensile?', ['1600 euro', '2000 euro', '4800 euro', '6400 euro'], '(40 − 30) × 160 = 1600.'),
      mc('Quanti pezzi servono, con margine di 10 euro, per eguagliare un utile di 2000?', ['200', '160', '100', '250'], '2000 ÷ 10 = 200.'),
      mc('Una catena con anelli al 70% e al 50%, dipendenti l’uno dall’altro, ha probabilità...', ['35%', '60%', '120%', '20%'], '0,7 × 0,5 = 0,35.'),
      mc('Con la matrice dello sconto, lo sconto conviene se la probabilità q che il concorrente abbassi è...', ['Sotto 0,6', 'Sopra 0,6', 'Sempre', 'Mai'], '2600 − 1600q > 2000 − 600q per q < 0,6.'),
      mc('Se il concorrente reagisce sempre al tuo sconto, quale confronto è pertinente?', ['Sconto, lui abbassa (1000), contro mantieni, lui mantiene (2000)', 'Sconto, lui mantiene (2600), contro mantieni, lui mantiene (2000)', 'La media aritmetica di tutte e quattro le celle della matrice', 'Il valore più alto presente nell’intera matrice dei profitti'], 'La reazione dipende dalla tua mossa.'),
      mc('Quale NON è una buona pratica per un piano contingente?', ['Fissare la soglia solo dopo aver visto i dati, per adattarla al piano', 'Fissare la soglia prima di cominciare il progetto, a mente fredda', 'Misurare il segnale su più giorni invece che su uno solo', 'Prevedere in anticipo il costo del passaggio al piano B'], 'Spostare la soglia dopo aver visto i dati è autoinganno.'),
      fill('Completa: 900 euro di spesa e 60 iscritti danno un costo di ___ euro per iscritto.', ['15'], '900 ÷ 60 = 15.'),
      fill('Completa: budget 3000 con riserva del 20%: restano ___ euro da allocare.', ['2400'], '3000 − 600 = 2400.'),
      order('Ordina le parti di un piano contingente', ['piano A', 'segnale e soglia', 'piano B', 'piano C'], 'Dal principale alle alternative con la soglia decisa prima.')
    ],
    test: [
      mc('Qual è il caso peggiore per la riga «sconto» nella matrice (2600, 1000)?', ['1000', '2600', '1400', '2000'], 'Il minimo della riga è 1000.'),
      mc('Con la regola del caso peggiore, quale riga si sceglie (sconto 1000, mantieni 1400)?', ['Mantieni', 'Sconto', 'Nessuna', 'Entrambe uguali'], '1400 è maggiore di 1000.'),
      mc('Perché conviene decidere la soglia di passaggio in anticipo?', ['Perché a mente fredda non si è condizionati dal coinvolgimento', 'Perché i numeri scelti prima risultano sempre più grandi', 'Perché così non serve più misurare il segnale durante il progetto', 'Perché il piano B in questo modo non deve nemmeno esistere'], 'Una soglia fissata dopo è influenzata dalla preferenza.'),
      mc('Che cosa non prova un esercizio con matrici di utili assegnati?', ['Che gli avversari reali si comportino come nella matrice', 'Che sai leggere una matrice di utili a due mosse', 'Che sai valutare il caso peggiore di ciascuna riga', 'Che sai confrontare le righe di una stessa tabella'], 'Gli avversari reali non sono mai così pienamente definiti.'),
      fill('Completa: la probabilità di una catena si ottiene moltiplicando le probabilità ___ dei suoi anelli.', ['condizionate'], 'Ogni anello è condizionato al precedente.')
    ] });

  /* ================= PLN · L4 ================= */
  T({ id: 'sma-pln-l4-progetti-reali-imprevisti', pillar: 'pln', stage: 'L4', title: 'Nella vita reale: progetti, imprevisti e stime',
    summary: 'Pianificare un progetto quotidiano con un buffer calibrato, segnali anticipatori e un registro di stime ed esiti che corregge nel tempo le tue previsioni di durata.',
    objectives: ['Correggere una stima di durata con un fattore ricavato dai tuoi progetti passati', 'Definire segnali anticipatori e soglie per un progetto reale', 'Fare una revisione senza colpa che separi errori di pianificazione, di esecuzione e imprevisti veri'],
    prereq: ['sma-pln-l3-conseguenze-avversari-contingenze'], minutes: 20,
    pages: [
      { h: 'Scegliere un progetto reale piccolo', b: `Da qui in poi il test è nella vita. Scegli un progetto con queste caratteristiche:\n\n- **Durata da 3 giorni a 4 settimane** (così vedi l’esito in tempi utili).\n- **Più passi e almeno un’incognita**: un trasloco di una stanza, un viaggio di 3 giorni, la preparazione di un esame, l’ordine delle carte di casa, la sostituzione di un dispositivo.\n- **Esito controllabile da te**, in modo che l’errore sia il tuo da analizzare, non una decisione altrui.\n- **Costo di sbagliare contenuto.**\n\n> Esempi: «Preparare l’archivio digitale di un anno di ricevute entro 3 settimane», «Organizzare un fine settimana fuori con budget di 600 euro», «Finire un corso online di 10 lezioni in 4 settimane».\n\nCosa non scegliere come primo progetto: decisioni su salute, grandi somme di denaro, rapporti personali delicati. Per quelle serve un professionista o una persona di fiducia, non solo un registro.\n\n**Scrivi il progetto in tre righe:** obiettivo con scadenza, i 4–6 passi principali, e i due vincoli più forti.` },
      { h: 'La stima ottimistica e il fattore di correzione', b: `Quasi tutti sottostimano la durata dei propri compiti: è l’errore detto **fallacia della pianificazione**. La correzione più semplice è la **classe di riferimento**: guardare quanto hanno richiesto **i tuoi compiti simili del passato**, non solo quanto pensi richiederà questo.\n\n**Caso svolto.** Cinque attività recenti, stima contro realtà (ore):\n\n- Attività 1: stimate 4, reali 6.\n- Attività 2: stimate 6, reali 9.\n- Attività 3: stimate 3, reali 4.\n- Attività 4: stimate 8, reali 12.\n- Attività 5: stimate 5, reali 6.\n\nTotale stimato **26 ore**, totale reale **37 ore**. Fattore = 37 ÷ 26 = **1,42** (le attività sono durate in media il 42% in più).\n\nPer un nuovo compito che stimi in 20 ore: 20 × 1,42 ≈ **28 ore**. Non è una profezia: è una stima più onesta, basata sulla tua storia.\n\n**Limiti:** il campione è piccolo (5 attività) e le attività non erano tutte simili. Meglio dichiarare un intervallo (per esempio «tra 24 e 32 ore»), e **aggiornare il fattore** ogni volta che hai nuovi dati. Se il fattore resta intorno a 1,4 per mesi, è parte del tuo modo di lavorare e va incorporato nei piani.` },
      { h: 'Buffer e riserve calibrati', b: `Il buffer non è un margine casuale: è una **parte dichiarata** del piano.\n\n> Un viaggio di 3 giorni con budget di 600 euro. Regola: riserva del 15% = **90 euro**. Restano **510 euro** da allocare: trasporti 210, alloggio 190, pasti 110 (totale 510). La riserva copre un cambio di treno, un pasto in più, un biglietto dimenticato.\n\n- **Buffer di tempo:** metti margini maggiori nei **passaggi critici** (coincidenze, consegne ad altri, scadenze di terzi) e minori nei passi che dipendono solo da te.\n- **Buffer in fondo, non in mezzo:** un margine sparso tra i passi tende a essere consumato dai primi; un margine in coda protegge la scadenza finale.\n- **Una regola di uso:** se il buffer è consumato per più di metà prima di metà progetto, **segnalalo** e rivedi il piano.\n\nUn buffer **non usato** non è un errore: significa che il piano ha funzionato. Spendere la riserva solo perché esiste è invece un modo per perdere margine.\n\nE se gli altri dipendono da te, **comunica presto** i ritardi: avvisare con una settimana di anticipo costa poco, avvisare il giorno prima costa molto.` },
      { h: 'Segnali anticipatori e soglie', b: `Per ogni progetto scegli **uno o due indicatori** che ti avvisano in tempo, con **una soglia scritta prima**.\n\n> **Esame:** pagine studiate a metà tempo. Soglia: meno del 40% del totale → riduci il perimetro o aggiungi sessioni.\n> **Viaggio:** prenotazioni confermate a 7 giorni dalla partenza. Soglia: manca una prenotazione chiave → attiva il piano B (alloggio alternativo già individuato).\n> **Archivio ricevute:** ricevute caricate a fine prima settimana. Soglia: meno di 1/3 → cambia metodo, per esempio ricevute raccolte in batch.\n\nTipi di indicatore:\n- **Di avanzamento** (quanto fatto).\n- **Di qualità** (errori trovati nel controllo).\n- **Di rischio** (un fornitore non risponde da 3 giorni).\n- **Di ritmo** (tempo medio per unità di lavoro).\n\nGli indicatori di rischio arrivano **prima** e quindi sono i più preziosi.\n\n**Non osservare solo ciò che conferma.** Se sei convinto che andrà bene, noterai le notizie buone. Chiedi a te stesso ogni settimana: **«Quale segnale mi direbbe che sto andando male, e l’ho guardato?»**` },
      { h: 'Il registro di stime ed esiti', b: `Un registro di pianificazione ha cinque colonne per ogni progetto o compito:\n\n1. **Che cosa** (una riga).\n2. **Stima iniziale** (con intervallo).\n3. **Stima corretta** (dopo il fattore).\n4. **Esito reale**.\n5. **Scarto e motivo** (una riga).\n\n> Esempio: «Ordinare l’archivio» — stima iniziale 6 ore (5–8); stima corretta 8,5 ore; reale 9 ore; scarto +0,5 rispetto alla corretta (+3 rispetto all’iniziale); motivo: scansioni da rifare.\n\nOgni mese, calcola:\n- **Fattore medio** reale/stimato.\n- **Quante volte** l’esito reale è dentro l’intervallo dichiarato (se ti capita solo il 40% delle volte, gli intervalli sono troppo stretti).\n- **Categoria prevalente** di errori (stima, esecuzione, imprevisti esterni).\n\nIl registro serve a **confrontare previsioni ed esiti** con numeri tuoi, non a giudicarti. E conta soprattutto la **tendenza**: se il fattore scende da 1,6 a 1,2 in tre mesi, stai migliorando in modo osservabile.\n\n**Privacy:** non registrare dati sensibili altrui; descrivi i compiti in modo che il registro sia utile anche se lo rileggi tra un anno.` },
      { h: 'Revisione senza colpa', b: `Alla fine di ogni progetto dedica 15 minuti a una revisione in tre domande:\n\n1. **Che cosa è andato come previsto?** (conferma ciò che funziona)\n2. **Che cosa no, e dove si è rotto il ragionamento?**\n3. **Che cosa cambio la prossima volta, in una riga?**\n\nPer il punto 2 distingui tre categorie, perché hanno rimedi diversi:\n- **Errore di pianificazione:** la stima o l’elenco dei passi era sbagliato (rimedio: fattore di correzione, passi dimenticati).\n- **Errore di esecuzione:** il piano era buono ma non l’hai seguito (rimedio: segnali anticipatori, ambiente, abitudini).\n- **Imprevisto esterno:** non dipendeva da te (rimedio: riserva e contingenze, non la colpa).\n\n> Esempio: hai finito 3 giorni dopo. Revisione: 1 giorno perso per un rinvio di un fornitore (imprevisto esterno: la riserva non lo copriva, nel prossimo piano aggiungo una verifica anticipata); 2 giorni per stima ottimistica (pianificazione: applico il fattore 1,4).\n\nAttenzione all’**errore di esito**: un progetto andato bene non dimostra che il piano fosse buono (potevi essere fortunato), e uno andato male non dimostra il contrario.\n\n**Cosa prova questo livello.** Solo il progetto reale mostra se i metodi ti aiutano: gli esercizi qui sotto verificano che sai calcolare e leggere un registro, non che abbia funzionato nella tua vita. Ed è corretto dire che i miglioramenti si misurano su **molti** progetti, non su uno.` }
    ],
    exercises: [
      mc('Quale scelta è più adatta come primo progetto reale?', ['Organizzare un fine settimana fuori con budget di 600 euro', 'Decidere una terapia medica da seguire per un problema', 'Investire tutti i risparmi che hai accumulato in tanti anni', 'Risolvere un conflitto familiare molto delicato e di lunga data'], 'Durata breve, esito controllabile e costo contenuto.'),
      mc('Ore stimate 26 e reali 37: fattore di correzione?', ['1,42', '0,70', '1,11', '1,30'], '37 ÷ 26 ≈ 1,42.'),
      mc('Con fattore 1,42, un compito stimato in 20 ore diventa circa...', ['28 ore', '22 ore', '35 ore', '24 ore'], '20 × 1,42 ≈ 28,4.'),
      mc('Perché il buffer è meglio in fondo al progetto?', ['Un margine sparso si consuma presto e non protegge la scadenza', 'Perché in fondo al progetto il margine può essere ignorato', 'Perché così il piano complessivo risulta più corto sulla carta', 'Perché i ritardi accadono sempre solo negli ultimi giorni'], 'Il margine in coda protegge la scadenza finale.'),
      mc('Quale indicatore è di rischio?', ['Un fornitore non risponde da 3 giorni', 'Le pagine studiate fino a metà del tempo previsto', 'Le ore dedicate al progetto nell’ultima settimana', 'Il numero di righe che occupa il piano scritto'], 'Segnala un problema potenziale prima che si manifesti.'),
      mc('Hai finito 3 giorni dopo: 1 per rinvio di un fornitore, 2 per stima ottimistica. Quali categorie?', ['Imprevisto esterno e errore di pianificazione', 'Errore di esecuzione e imprevisto esterno', 'Due errori di esecuzione distinti tra loro', 'Nessun errore, solo sfortuna nell’ultima fase'], 'Il rinvio non dipendeva da te; la stima era ottimistica.'),
      fill('Completa: budget 600 con riserva del 15%: la riserva è di ___ euro.', ['90'], '600 × 0,15 = 90.'),
      fill('Completa: un fattore medio di 1,5 su un compito stimato in 10 ore dà ___ ore.', ['15'], '10 × 1,5 = 15.'),
      order('Ordina le domande di una revisione senza colpa', ['che cosa è andato come previsto', 'dove si è rotto il ragionamento', 'che cosa cambio'], 'Prima conferma, poi analisi, poi azione.')
    ],
    test: [
      mc('Cinque compiti: stimati 10 ore in tutto, reali 15. Fattore?', ['1,5', '0,67', '1,2', '2'], '15 ÷ 10 = 1,5.'),
      mc('Se solo il 40% dei tuoi esiti cade nell’intervallo dichiarato, che cosa suggerisce?', ['Gli intervalli sono troppo stretti', 'Gli intervalli sono troppo larghi', 'Il fattore di correzione è già perfetto', 'Il registro non serve a nulla'], 'Troppi esiti fuori intervallo: eccesso di fiducia.'),
      mc('Che cos’è l’errore di esito?', ['Giudicare un piano solo da come è andato', 'Dimenticare di aggiornare il registro a fine mese', 'Usare un buffer troppo grande per il progetto', 'Scegliere indicatori sbagliati per il progetto'], 'Un piano buono può avere esito cattivo e viceversa.'),
      mc('Che cosa prova un esercizio simulato di pianificazione e che cosa no?', ['Che sai leggere un registro, non che migliori nella vita reale', 'Che pianificherai sempre bene qualunque progetto ti capiti', 'Che non avrai mai imprevisti nei tuoi prossimi progetti', 'Che il fattore di correzione trovato valga per sempre'], 'Solo progetti reali mostrano l’efficacia.'),
      fill('Completa: sottostimare sistematicamente la durata dei propri compiti si chiama fallacia della ___.', ['pianificazione'], 'Si corregge con la classe di riferimento.')
    ] });

  /* ================= PLN · L5 ================= */
  T({ id: 'sma-pln-l5-integrazione-robustezza-etica', pillar: 'pln', stage: 'L5', title: 'Integrare i modelli: robustezza, punti deboli ed etica',
    summary: 'Scegliere tra piani con criteri che possono divergere, cercare i punti deboli di una strategia prima che li trovi il mondo e correggersi con evidenze ripetute.',
    objectives: ['Confrontare piani con più criteri (valore atteso, caso peggiore, rimpianto massimo) e spiegare perché possono divergere', 'Condurre un esame dei punti deboli di una strategia con una prova di fallimento anticipata', 'Motivare una scelta con obiettivi in conflitto, dichiarando limiti, costi etici e cosa la cambierebbe'],
    prereq: ['sma-pln-l4-progetti-reali-imprevisti'], minutes: 20,
    pages: [
      { h: 'Quando i criteri non concordano', b: `Nei livelli precedenti hai usato il **valore atteso**, il **caso peggiore** e il confronto fra piani. Nei problemi veri questi criteri possono dare **risposte diverse**, e il lavoro è capire perché e scegliere con consapevolezza.\n\n**Caso svolto.** Devi scegliere tra tre piani per consegnare un lavoro a un cliente. Tre scenari: **S1** il cliente chiede la consegna subito; **S2** tempi normali; **S3** il cliente ritarda i propri materiali. Valori (0–10, ipotesi didattiche):\n\n- **P1** (tutto in anticipo con un fornitore esterno): 10, 4, 2.\n- **P2** (lavoro interno con riserva): 7, 6, 5.\n- **P3** (aspettare e fare in casa): 5, 5, 9.\n\n**Valore atteso con scenari ugualmente probabili:** P1 = 5,33; P2 = 6; **P3 = 6,33**.\n**Caso peggiore (maximin):** P1 = 2; P2 = 5; P3 = 5 (**parità** tra P2 e P3).\n**Rimpianto massimo:** il migliore per scenario vale 10, 6, 9. Il rimpianto di P1 è 0, 2, 7 (massimo **7**); di P2 è 3, 0, 4 (massimo **4**); di P3 è 5, 1, 0 (massimo **5**). Rimpianto minimo: **P2**.\n\nTre criteri, tre risposte parziali: P3, P2 o P3, P2. Non c’è un errore di calcolo: i criteri **misurano cose diverse**.` },
      { h: 'Che cosa misura ciascun criterio', b: `- **Valore atteso:** rende al meglio **in media** se ripeti molte scelte simili. Dipende dalle **probabilità degli scenari**, che sono stime.\n- **Caso peggiore:** protegge dal danno massimo. È adatto quando un fallimento è **irreversibile** o l’esito grave non può essere assorbito.\n- **Rimpianto massimo:** protegge dal **rimpiangere di più** una scelta rispetto alla migliore possibile. È adatto quando la scelta sarà **giudicata a posteriori** o quando non hai stime affidabili delle probabilità.\n\nProva a cambiare le probabilità degli scenari: **0,5 / 0,3 / 0,2**. Valori attesi: P1 = 0,5 × 10 + 0,3 × 4 + 0,2 × 2 = **6,6**; P2 = 0,5 × 7 + 0,3 × 6 + 0,2 × 5 = **6,3**; P3 = 0,5 × 5 + 0,3 × 5 + 0,2 × 9 = **5,8**. Ora il valore atteso preferisce **P1**: con probabilità diverse la classifica si ribalta.\n\nQuindi: **P2 è robusta** (buona in ogni scenario, mai tra le peggiori), P1 è **la scommessa** (ottima se il cliente ha fretta, brutta se ritarda), P3 è **l’attesa**.\n\n> Domanda guida: **«Che cosa posso permettermi di perdere, e quanto sono sicuro delle mie stime?»** Se le stime sono deboli e un esito grave sarebbe costoso, la robustezza (P2) vale più del guadagno atteso.` },
      { h: 'Cercare i punti deboli prima del mondo', b: `Ogni strategia dipende da **assunzioni**. Spesso le tue assunzioni più pericolose sono quelle che non hai scritto. Tre tecniche per portarle alla luce:\n\n1. **Prova di fallimento anticipata** (pre-mortem): immagina che sia passato un anno e che il piano sia **fallito**. Scrivi in 5 minuti **perché**. Poi trasforma ogni causa in un controllo o in una contingenza.\n2. **Assunzioni esplicite**: per ogni passo scrivi «questo funziona se…» e dai una probabilità.\n3. **Avvocato del diavolo (red team)**: una persona (o tu in un secondo momento, con un ruolo diverso) cerca di **rompere** il piano. Vale solo se chi critica è **autorizzato** a dire di no.\n\n> Esempio: piano «lanciare il servizio il 1º ottobre con il fornitore A». Pre-mortem: «Il fornitore A ha ritardato la consegna», «il test di carico non è stato fatto», «l’unica persona che sapeva configurarlo era in ferie». Controlli: contratto con penale, test in settembre, seconda persona formata.\n\n**Attenzione al calcolo dell’affidabilità:** una catena di 5 passi, ciascuno con probabilità di successo del 90%, riesce con 0,9⁵ ≈ **59%**. Un piano con molti passi dipendenti è **fragile** anche se ogni passo sembra sicuro. Accorcia la catena o aggiungi alternative nei passaggi più deboli.` },
      { h: 'Obiettivi e vincoli in conflitto, con etica', b: `A volte due obiettivi legittimi non si possono soddisfare entrambi: **velocità e qualità**, **costo e sicurezza**, **interesse tuo e di un’altra persona**. La procedura:\n\n1. **Dichiara gli obiettivi** e **di chi sono**.\n2. **Individua i vincoli non negoziabili**: sicurezza di persone, leggi, impegni presi.\n3. **Scarta le opzioni che li violano**, anche se convenienti.\n4. **Tra le restanti, confronta** con i criteri visti sopra.\n5. **Motiva** la scelta in poche righe e **dichiara chi paga** i costi.\n\n> Esempio: un team può consegnare una funzione in tempo (obiettivo del cliente) tagliando i test di sicurezza (vincolo non negoziabile per gli utenti). L’opzione «taglia i test» viene **scartata** al punto 3. Restano: consegnare in ritardo con test completi, o consegnare in tempo una versione ridotta, con test completi. Si confrontano per costo e rischio.\n\n**Regola etica del modulo.** Un piano non è buono se funziona **solo nascondendo** informazioni rilevanti a chi ne subisce le conseguenze, o se richiede di **costringere** qualcuno. Verifica: **«Potrei spiegare questo piano alle persone coinvolte senza che lo rifiutino come ingiusto?»** Se la risposta è no, il piano ha un punto debole che non appare nelle tabelle.\n\nNota che l’etica non è un ostacolo alla strategia: i piani che dipendono dall’inganno sono anche **fragili**, perché basta che l’inganno emerga per perdere fiducia e risorse.` },
      { h: 'Problemi nuovi e aperti', b: `Alcuni problemi non somigliano a nessuno di quelli che hai già risolto. Strategie di lavoro:\n\n- **Scomponi** in sottoproblemi che riconosci.\n- **Cerca un’analogia** con un caso noto, ma dichiara dove **non** regge.\n- **Parti da una versione più semplice** (meno attori, meno vincoli) e aggiungi complessità.\n- **Rendi reversibili** i primi passi: impara con piccoli esperimenti prima di impegnarti.\n- **Separa ciò che sai da ciò che supponi**: ricordi il primo modulo? Funziona anche qui.\n- **Accetta di non sapere**: a volte la migliore mossa è ritardare con una soglia chiara («ridecido il 15, quando avrò due dati in più»).\n\n> Esempio di problema aperto: un piccolo gruppo di volontari deve organizzare la distribuzione di materiale a 300 famiglie con poco tempo, una sede e due furgoni. Non esiste uno schema già pronto. Scomposizione: raccolta dati, logistica, comunicazione, responsabilità. Versione semplice: 30 famiglie in un quartiere. Primo passo reversibile: una prova con 30 famiglie e un giro di feedback. Ipotesi dichiarate: «i furgoni bastano se le consegne sono per zona».\n\nIl risultato non è un piano perfetto, è un **piano rivedibile con soglie chiare**.` },
      { h: 'Autocorrezione ed evidenze ripetute', b: `A questo livello la domanda non è «ho capito?», ma «**le mie previsioni e i miei piani migliorano nel tempo, in situazioni diverse?**»\n\nCome si legge un registro dopo mesi:\n\n- **Più progetti**, non uno solo: almeno 6–10 con previsioni e esiti scritti.\n- **Più contesti**: lavoro, studio, soldi di base, viaggi.\n- **Senza aiuti**: quanti dei piani li hai fatti senza checklist e senza suggerimenti.\n- **Errori analizzati**: per ognuno, categoria e modifica concreta.\n- **Tendenza** nel fattore di correzione e nella quota di esiti dentro l’intervallo.\n\n> Esempio: il fattore medio ore reali / ore stimate passa da 1,6 (primi 4 progetti) a 1,25 (ultimi 4): un miglioramento osservabile, anche se otto progetti non bastano per una conclusione definitiva.\n\n**Che cosa NON significa raggiungere L5.** Non significa prevedere il futuro, vincere contro chiunque, né avere una competenza valida in ogni campo. Significa aver mostrato, **in modo ripetuto e misurato**, di saper integrare modelli, riconoscere punti deboli, correggersi, motivare decisioni e rispettare i vincoli etici. Gli esercizi simulati provano la parte di ragionamento; la parte di **applicazione reale** richiede prove reali, e resta sempre aperta: nessuno finisce di imparare a pianificare.` }
    ],
    exercises: [
      mc('Con scenari equiprobabili, quale piano ha il valore atteso maggiore (P1 10-4-2, P2 7-6-5, P3 5-5-9)?', ['P3', 'P1', 'P2', 'P1 e P2 pari'], 'P3 = 6,33; P2 = 6; P1 = 5,33.'),
      mc('Quale piano ha il rimpianto massimo più basso?', ['P2 (rimpianto massimo 4)', 'P1 (rimpianto massimo 7)', 'P3 (rimpianto massimo 5)', 'Tutti uguali'], 'P2 ha rimpianti 3, 0, 4.'),
      mc('Con probabilità 0,5, 0,3, 0,2, il valore atteso di P1 è...', ['6,6', '6,3', '5,8', '5,3'], '5 + 1,2 + 0,4 = 6,6.'),
      mc('Perché il caso peggiore è utile quando un fallimento è irreversibile?', ['Protegge dal danno che non potresti recuperare', 'Perché è il più semplice da calcolare a mano', 'Perché i casi peggiori sono sempre i più probabili', 'Perché garantisce comunque il massimo valore atteso'], 'Si evita l’esito che non si può assorbire.'),
      mc('Una catena di 5 passi con probabilità di successo del 90% ciascuno, supposti indipendenti, riesce con probabilità...', ['Circa 59%', 'Circa 90%', 'Circa 45%', 'Circa 81%'], '0,9⁵ = 0,59049.'),
      mc('Che cos’è una prova di fallimento anticipata (pre-mortem)?', ['Immaginare il piano fallito e scrivere perché, per creare controlli', 'Annullare il piano prima di cominciare per non perdere risorse', 'Valutare il piano soltanto a fine progetto, con i dati reali', 'Chiedere a tutti i partecipanti se sono d’accordo con il piano'], 'Porta alla luce assunzioni non dichiarate.'),
      mc('Quale NON è un passaggio corretto con obiettivi in conflitto?', ['Tenere l’opzione che viola un vincolo di sicurezza se conviene', 'Dichiarare apertamente chi paga i costi della scelta fatta', 'Scartare le opzioni che violano i vincoli non negoziabili', 'Dire apertamente che cosa cambierebbe la decisione presa'], 'I vincoli non negoziabili escludono le opzioni.'),
      fill('Completa: 0,9 elevato alla quinta, arrotondato in percentuale all’intero, vale ___ percento.', ['59'], '0,59049.'),
      fill('Completa: il criterio che minimizza il maggior dispiacere rispetto alla scelta migliore si chiama minimo ___ massimo.', ['rimpianto'], 'Minimax regret.'),
      order('Ordina il lavoro su obiettivi in conflitto', ['dichiaro obiettivi e di chi sono', 'individuo i vincoli non negoziabili', 'scarto le opzioni che li violano', 'confronto le restanti', 'motivo e dichiaro chi paga'], 'Prima i limiti, poi il confronto.')
    ],
    test: [
      mc('Se hai stime deboli e un esito grave sarebbe costoso, che cosa pesa di più?', ['La robustezza della scelta', 'Il valore atteso con le stime più ottimistiche', 'La scelta più veloce', 'La scelta più originale'], 'Con stime deboli il caso peggiore e il rimpianto contano.'),
      mc('Quale domanda etica serve come verifica?', ['Potrei spiegare il piano a chi coinvolge senza che lo senta ingiusto?', 'Quanto sarebbe difficile scoprire che il piano ha un punto debole?', 'Quante persone lo approverebbero se non fossero informate?', 'Quanto guadagnerei se nessuno venisse a conoscenza dei dettagli?'], 'Se il piano regge solo nascondendo, è fragile ed eticamente problematico.'),
      mc('Che cosa non dimostra l’aver raggiunto L5 nell’app?', ['Una competenza in ogni campo o la capacità di prevedere il futuro', 'Prestazioni misurate dentro questa app, nelle prove svolte', 'Un uso ripetuto dei modelli su casi diversi tra loro', 'La capacità di dichiarare i limiti di una conclusione'], 'L5 descrive prestazioni misurate qui, non competenza universale.'),
      mc('Quali evidenze rendono più credibile un miglioramento nel tempo?', ['Più progetti, contesti diversi, senza aiuti, con errori analizzati', 'Un solo progetto riuscito molto bene, documentato con cura', 'Aver letto tutti i moduli del percorso fino all’ultimo', 'Un ottimo risultato ottenuto in un singolo esercizio simulato'], 'Ripetizione e varietà contano.'),
      fill('Completa: un piano con molti passi dipendenti è ___ anche se ogni passo sembra sicuro.', ['fragile'], 'Le probabilità si moltiplicano.')
    ] });
})(window.ST = window.ST || {});
